INSERT INTO public.topics (id, title, slug, usmle_step, "order", section, is_free_demo, mcq_count, case_count)
INSERT INTO public.mcqs (topic_id, question, options, correct_index, explanation, difficulty, "order", type) VALUES
('82e55873-64d5-4a12-bc71-535983609a64', 'A 68-year-old man with chronic obstructive pulmonary disease presents with 3 days of fever, productive cough, and dyspnea. His temperature is 39.2 C, heart rate 118/min, blood pressure 82/50 mm Hg, and respiratory rate 24/min. Laboratory studies show a white blood cell count of 18,000/microL and a lactate level of 4.8 mmol/L. Chest radiograph shows a right lower lobe infiltrate. He receives 30 mL/kg of intravenous crystalloid and broad-spectrum antibiotics, but his blood pressure remains 84/52 mm Hg. What is the most appropriate next step in management?', '["Administer intravenous hydrocortisone", "Start a dobutamine infusion", "Give an additional 30 mL/kg of intravenous crystalloid", "Give intermittent phenylephrine boluses", "Start a norepinephrine infusion"]'::jsonb, 4, 'This patient has septic shock from pneumonia with persistent hypotension despite adequate fluid resuscitation, so a vasopressor is indicated. Norepinephrine is the first-line vasopressor for septic shock because it raises mean arterial pressure through alpha-adrenergic vasoconstriction with modest beta-1 activity and has the best mortality data. Hydrocortisone is reserved for refractory shock when vasopressors are inadequate. Dobutamine is used only when there is evidence of myocardial dysfunction with persistent hypoperfusion despite fluids and vasopressors. Additional fluid boluses are unlikely to help after 30 mL/kg in a patient who remains hypotensive, and phenylephrine boluses are not a substitute for a continuous first-line vasopressor infusion.', 'Medium', 1, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 45-year-old woman presents to the emergency department with fever, chills, and dysuria for 2 days. Her temperature is 39.0 C, heart rate 122/min, blood pressure 88/54 mm Hg, and respiratory rate 22/min. She has right costovertebral angle tenderness. Laboratory studies show a white blood cell count of 16,000/microL and a lactate level of 3.2 mmol/L. Urinalysis is positive for leukocyte esterase and nitrites. What is the most appropriate initial management?', '["Administer broad-spectrum antibiotics immediately without obtaining cultures", "Obtain blood cultures and then give broad-spectrum antibiotics within 1 hour", "Wait for urine culture results before starting antibiotics", "Give intravenous fluids only and observe for 6 hours", "Start a vasopressor infusion before giving antibiotics"]'::jsonb, 1, 'This patient meets criteria for sepsis from a urinary source, and the Surviving Sepsis Campaign bundle requires blood cultures followed by broad-spectrum antibiotics within 1 hour of recognition. Cultures must be obtained before antibiotics when this does not delay administration, because prior antibiotics reduce culture yield. Giving antibiotics without cultures wastes the opportunity to identify the pathogen and tailor therapy. Waiting for culture results delays life-saving treatment and increases mortality. Fluids alone are insufficient without prompt antibiotics, and vasopressors are indicated only if hypotension persists after fluid resuscitation, not before antibiotics are given.', 'Medium', 2, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 72-year-old man is on postoperative day 5 after a sigmoid colectomy for diverticulitis. He develops fever to 39.1 C, worsening abdominal pain, and tachycardia. His white blood cell count is 19,000/microL. Computed tomography of the abdomen shows a 6-cm rim-enhancing fluid collection adjacent to the anastomosis with a small amount of free fluid. He is hemodynamically stable. What is the most appropriate next step in management?', '["Continue broad-spectrum antibiotics alone", "Proceed to exploratory laparotomy", "Perform CT-guided percutaneous drainage of the collection", "Repeat CT imaging in 48 hours", "Place a nasogastric tube for decompression"]'::jsonb, 2, 'This patient has a postoperative intra-abdominal abscess, and source control is essential in addition to antibiotics. A well-defined, accessible 6-cm collection is best managed with CT-guided percutaneous drainage, which is less invasive than surgery and highly effective for localized abscesses. Antibiotics alone cannot sterilize a large undrained collection. Exploratory laparotomy is reserved for generalized peritonitis, free perforation, or collections not amenable to percutaneous drainage. Repeating imaging without intervention delays source control, and nasogastric decompression does nothing to treat an established abscess.', 'Hard', 3, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 59-year-old woman with septic shock secondary to pneumonia is receiving norepinephrine at 0.5 mcg/kg/min after adequate fluid resuscitation and broad-spectrum antibiotics. Her mean arterial pressure remains 58 mm Hg, her lactate level is 5.1 mmol/L, and her urine output is 15 mL/hr. Her central venous oxygen saturation is 68 percent and her cardiac output is normal. What is the most appropriate next step in management?', '["Add intravenous hydrocortisone", "Switch norepinephrine to phenylephrine", "Add a dobutamine infusion", "Add vasopressin as a second vasopressor", "Give another 30 mL/kg bolus of crystalloid"]'::jsonb, 3, 'Vasopressin is the recommended second-line vasopressor when mean arterial pressure remains below target despite norepinephrine, because it raises vascular tone through a different receptor pathway and allows the norepinephrine dose to be reduced. Hydrocortisone is considered only when shock remains refractory despite adequate vasopressor support, not as the next step. Phenylephrine is not superior to norepinephrine and lacks its beta-1 activity. Dobutamine is indicated for low cardiac output with persistent hypoperfusion, but this patient has a normal cardiac output. Additional fluids are unlikely to help after adequate resuscitation and risk volume overload.', 'Hard', 4, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 38-year-old previously healthy man presents with 4 days of cough productive of yellow sputum, fever to 38.5 C, and pleuritic chest pain. He has no chronic medical conditions, takes no medications, and has no drug allergies. His vital signs are stable, and his oxygen saturation is 97 percent on room air. Chest radiograph shows a right lower lobe infiltrate without effusion. What is the most appropriate treatment?', '["Oral amoxicillin", "Intravenous ceftriaxone plus azithromycin", "Intravenous vancomycin", "Intravenous piperacillin-tazobactam", "Supportive care with no antibiotics"]'::jsonb, 0, 'This is outpatient community-acquired pneumonia in a healthy adult without comorbidities or risk factors for drug-resistant pathogens. Oral amoxicillin monotherapy is an appropriate guideline-recommended regimen for this population, as is doxycycline or a macrolide. Intravenous ceftriaxone plus azithromycin is an inpatient regimen and is unnecessarily broad for a stable outpatient. Vancomycin and piperacillin-tazobactam are reserved for patients with risk factors for methicillin-resistant Staphylococcus aureus or Pseudomonas, which this patient lacks. Antibiotics are indicated because this is bacterial pneumonia, so supportive care alone is inadequate.', 'Easy', 5, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 74-year-old man presents with 5 days of productive cough, fever, and worsening dyspnea. He is confused and disoriented. His temperature is 38.8 C, heart rate 112/min, respiratory rate 30/min, and blood pressure 100/60 mm Hg. Laboratory studies show a blood urea nitrogen of 24 mg/dL and a white blood cell count of 15,000/microL. Chest radiograph shows a left lower lobe infiltrate. What is the most appropriate management?', '["Admit to the hospital and start ceftriaxone plus azithromycin", "Discharge home on oral amoxicillin", "Discharge home on oral levofloxacin", "Start vancomycin monotherapy as an outpatient", "Admit directly to the intensive care unit for intubation"]'::jsonb, 0, 'This patient has a CURB-65 score of 3, with points for confusion, elevated urea, tachypnea, and age over 65, which predicts high mortality and mandates hospital admission. Inpatient treatment of community-acquired pneumonia is a beta-lactam such as ceftriaxone combined with a macrolide such as azithromycin to cover typical and atypical pathogens. Outpatient therapy with amoxicillin or levofloxacin is unsafe given his severity of illness. Vancomycin monotherapy does not cover the usual causes of community-acquired pneumonia. Intensive care admission and intubation are not indicated because he is not in respiratory failure or shock.', 'Medium', 6, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 66-year-old woman with chronic obstructive pulmonary disease presents with fever, productive cough, and dyspnea. She was hospitalized 3 weeks ago for a COPD exacerbation and received intravenous antibiotics. She is known to be colonized with methicillin-resistant Staphylococcus aureus. Chest radiograph shows a right upper lobe infiltrate with a small cavity. What is the most appropriate empiric antibiotic regimen?', '["Ceftriaxone plus azithromycin", "Vancomycin plus piperacillin-tazobactam", "Oral doxycycline", "Oral amoxicillin", "Azithromycin alone"]'::jsonb, 1, 'This patient has community-acquired pneumonia with strong risk factors for methicillin-resistant Staphylococcus aureus and Pseudomonas aeruginosa, including recent hospitalization, prior intravenous antibiotics, and known MRSA colonization. Empiric therapy must therefore include vancomycin for MRSA plus an antipseudomonal beta-lactam such as piperacillin-tazobactam to cover both resistant organisms. Ceftriaxone plus azithromycin is standard inpatient therapy but does not cover MRSA or Pseudomonas. Doxycycline, amoxicillin, and azithromycin alone are all inadequate for a patient with these risk factors and a cavitary infiltrate suggesting resistant organisms.', 'Hard', 7, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 52-year-old man presents with 6 days of high fever, dry cough, dyspnea, and watery diarrhea. He also reports confusion and muscle aches. His temperature is 39.4 C, heart rate 96/min, and blood pressure 118/76 mm Hg. Laboratory studies show a sodium level of 128 mEq/L and a mildly elevated aspartate aminotransferase. Chest radiograph shows a left lower lobe infiltrate. What is the most appropriate diagnostic test?', '["Sputum Gram stain and culture", "Blood cultures", "Legionella urinary antigen test", "Computed tomography of the chest", "Nasopharyngeal polymerase chain reaction for influenza"]'::jsonb, 2, 'The combination of pneumonia with hyponatremia, diarrhea, confusion, and relative bradycardia is classic for Legionella pneumophila infection, which is not reliably detected by sputum Gram stain because the organism stains poorly. The Legionella urinary antigen test is rapid, sensitive for serogroup 1, and is the preferred diagnostic test in this setting. Sputum Gram stain and blood cultures have low yield for Legionella. Chest CT would confirm the infiltrate but would not identify the pathogen. Influenza testing is less likely given the prominent extrapulmonary features and hyponatremia, which point toward Legionella.', 'Medium', 8, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 70-year-old man has been intubated in the intensive care unit for 7 days after a stroke. He develops a new fever to 39.0 C, increased purulent tracheal secretions, and worsening oxygen requirements. Chest radiograph shows a new right lower lobe infiltrate. His white blood cell count is 17,000/microL. What is the most appropriate next step in management?', '["Start ceftriaxone alone", "Extubate the patient immediately", "Obtain a chest CT scan", "Obtain endotracheal aspirate cultures and then start empiric vancomycin plus piperacillin-tazobactam", "Start nebulized antibiotics only"]'::jsonb, 3, 'This patient has ventilator-associated pneumonia, defined as pneumonia occurring more than 48 hours after intubation, and late-onset disease carries a high risk of multidrug-resistant organisms including Pseudomonas aeruginosa and methicillin-resistant Staphylococcus aureus. Respiratory cultures should be obtained before antibiotics, followed by empiric coverage with an antipseudomonal agent plus vancomycin. Ceftriaxone alone is far too narrow for late ventilator-associated pneumonia. Immediate extubation is unsafe in a patient with new hypoxemia and infection. Chest CT does not change management, and nebulized antibiotics are adjunctive at best and never a substitute for systemic therapy.', 'Medium', 9, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 64-year-old woman has been mechanically ventilated in the intensive care unit for 5 days after a motor vehicle collision. The care team is reviewing measures to prevent ventilator-associated pneumonia. Which of the following interventions is most effective for preventing ventilator-associated pneumonia?', '["Daily chest radiographs", "Prophylactic systemic antibiotics", "Routine stress ulcer prophylaxis", "Frequent ventilator circuit changes", "Head-of-bed elevation to 30-45 degrees with regular oral care"]'::jsonb, 4, 'Head-of-bed elevation to 30 to 45 degrees reduces aspiration of gastric contents, and regular oral care with chlorhexidine decreases oropharyngeal colonization, making this combination a core element of the ventilator bundle for preventing ventilator-associated pneumonia. Daily chest radiographs do not prevent pneumonia and are not routinely recommended. Prophylactic systemic antibiotics promote resistance and are not used for prevention. Stress ulcer prophylaxis may actually increase pneumonia risk by raising gastric pH and allowing bacterial overgrowth. Frequent ventilator circuit changes have no proven benefit and may increase contamination.', 'Easy', 10, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 63-year-old woman is hospitalized for a hip fracture and on hospital day 4 develops fever to 38.9 C, productive cough, and worsening oxygen requirements. She received a course of ceftriaxone 2 weeks ago for a urinary tract infection. Chest radiograph shows a new left lower lobe infiltrate. Sputum Gram stain shows gram-negative rods. What is the most appropriate empiric antibiotic regimen?', '["Piperacillin-tazobactam plus vancomycin", "Oral amoxicillin", "Ceftriaxone alone", "Azithromycin alone", "Oral doxycycline"]'::jsonb, 0, 'This patient has hospital-acquired pneumonia on day 4 with prior antibiotic exposure, which places her at high risk for multidrug-resistant organisms, particularly Pseudomonas aeruginosa and methicillin-resistant Staphylococcus aureus. Empiric therapy should therefore include an antipseudomonal beta-lactam such as piperacillin-tazobactam plus vancomycin for MRSA coverage. Amoxicillin and ceftriaxone alone do not cover Pseudomonas or MRSA, so they would leave the most likely pathogens untreated. Azithromycin and doxycycline are appropriate for atypical coverage in community-acquired pneumonia but are inadequate as monotherapy for hospital-acquired pneumonia with resistant-organism risk factors.', 'Medium', 11, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 26-year-old woman presents with 2 days of dysuria, urinary frequency, and urgency. She is afebrile and has no flank pain, vaginal discharge, or fever. She has no known drug allergies and is not pregnant. Urinalysis shows leukocyte esterase and 20 white blood cells per high-power field. What is the most appropriate treatment?', '["Ciprofloxacin for 7 days", "Nitrofurantoin for 5 days", "Intravenous ceftriaxone", "No treatment, reassurance only", "Amoxicillin-clavulanate for 14 days"]'::jsonb, 1, 'Uncomplicated cystitis in a young healthy woman is most often caused by Escherichia coli and is treated with a 5-day course of nitrofurantoin, which concentrates in the urine and is highly effective with minimal resistance. A 7-day course of ciprofloxacin is unnecessarily broad, promotes resistance, and carries risks of tendon injury and Clostridioides difficile infection. Intravenous ceftriaxone is reserved for complicated infection or pyelonephritis. No treatment is inappropriate because untreated cystitis causes ongoing symptoms and can ascend. Amoxicillin-clavulanate for 14 days is excessive in duration and spectrum for uncomplicated cystitis.', 'Easy', 12, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 34-year-old woman presents with 3 days of fever to 39.0 C, right flank pain, nausea, and vomiting. She has right costovertebral angle tenderness on examination. Laboratory studies show a white blood cell count of 16,000/microL. Urinalysis is positive for leukocyte esterase and nitrites with many white blood cells. Blood cultures are pending. What is the most appropriate management?', '["Oral nitrofurantoin", "Outpatient oral fosfomycin", "Intravenous ceftriaxone followed by oral antibiotics", "No antibiotics, supportive care only", "Computed tomography of the abdomen"]'::jsonb, 2, 'This patient has acute pyelonephritis, with fever, flank pain, costovertebral angle tenderness, vomiting, and leukocytosis indicating upper urinary tract infection. Nitrofurantoin and fosfomycin do not achieve adequate tissue levels in the kidney and are inappropriate for pyelonephritis. She requires an intravenous agent such as ceftriaxone initially, with transition to an oral antibiotic once she improves and susceptibilities return. No antibiotics is unsafe because untreated pyelonephritis can progress to sepsis. CT imaging is not needed for uncomplicated pyelonephritis in a young woman without obstruction or an atypical course.', 'Medium', 13, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 78-year-old man with an indwelling Foley catheter for 10 days after prostate surgery develops fever to 38.8 C, suprapubic discomfort, and cloudy urine. His white blood cell count is 14,000/microL. Urinalysis shows pyuria and bacteriuria. What is the most appropriate next step in management?', '["Start antibiotics without changing the catheter", "Obtain a urine culture from the existing catheter only", "Remove the catheter without obtaining a culture", "Replace the catheter and obtain a urine culture before starting antibiotics", "Perform bladder irrigation with sterile saline"]'::jsonb, 3, 'In catheter-associated urinary tract infection, the indwelling catheter is colonized with biofilm, so a urine culture from the old catheter is unreliable and antibiotics given through it often fail. The catheter should be removed or replaced and a fresh urine specimen obtained for culture before antibiotics are started. Starting antibiotics without changing the catheter leaves the source of infection in place. Culturing only from the existing catheter yields misleading results. Simply removing the catheter without culture misses the chance to identify the pathogen. Bladder irrigation does not treat infection and may introduce more organisms.', 'Medium', 14, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'An 82-year-old woman is found on routine urinalysis to have bacteriuria with 50,000 colony-forming units/mL of Escherichia coli. She reports no dysuria, frequency, urgency, fever, or flank pain. She is alert and hemodynamically stable, and her white blood cell count is normal. What is the most appropriate management?', '["Treat with ciprofloxacin for 7 days", "Treat with nitrofurantoin for 5 days", "Repeat the urine culture", "Obtain blood cultures", "No antibiotic treatment"]'::jsonb, 4, 'Asymptomatic bacteriuria should not be treated with antibiotics except in pregnant patients and those undergoing urologic procedures with mucosal bleeding. In an elderly woman without urinary symptoms, bacteriuria represents colonization and treatment provides no benefit while increasing the risk of adverse drug effects, Clostridioides difficile infection, and antimicrobial resistance. Ciprofloxacin and nitrofurantoin are both inappropriate here despite being effective urinary antibiotics. Repeating the urine culture does not change management in the absence of symptoms. Blood cultures are unnecessary without signs of systemic infection.', 'Easy', 15, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 44-year-old man presents with 2 days of progressive redness, warmth, and swelling of his left lower leg after a minor insect bite. He has a fever of 38.4 C. Examination shows unilateral erythema, warmth, and edema extending from the ankle to the mid-calf, with no fluctuance, bullae, or crepitus. There is no purulent drainage. What is the most appropriate treatment?', '["Oral cephalexin", "Intravenous vancomycin", "Incision and drainage", "Topical mupirocin", "Oral clindamycin"]'::jsonb, 0, 'This is uncomplicated nonpurulent cellulitis, most commonly caused by Streptococcus pyogenes or methicillin-sensitive Staphylococcus aureus, and a first-generation cephalosporin such as cephalexin is effective first-line therapy. Intravenous vancomycin is reserved for severe infection, methicillin-resistant Staphylococcus aureus, or failure of oral therapy, and is excessive here. Incision and drainage is indicated for a drainable abscess, but this patient has diffuse cellulitis without a fluctuant collection. Topical mupirocin does not penetrate deeply enough to treat cellulitis. Clindamycin is an alternative when there is penicillin allergy or suspected MRSA, but it is not first-line for uncomplicated streptococcal cellulitis.', 'Easy', 16, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 55-year-old man with diabetes mellitus presents with 12 hours of severe left leg pain, swelling, and fever. He says the pain is far worse than the appearance of the leg suggests. Examination shows tense edema, hemorrhagic bullae, and palpable crepitus over the calf. His blood pressure is 88/55 mm Hg and his heart rate is 124/min. Laboratory studies show a white blood cell count of 22,000/microL and a creatine kinase of 1,200 U/L. What is the most appropriate next step in management?', '["Oral cephalexin", "Emergent surgical debridement plus broad-spectrum intravenous antibiotics", "Wound culture and close observation", "Hyperbaric oxygen therapy alone", "Intravenous vancomycin alone"]'::jsonb, 1, 'Pain out of proportion to examination, bullae, crepitus, hypotension, and rapid progression in a diabetic patient are classic for necrotizing fasciitis, a surgical emergency with high mortality. The definitive treatment is emergent surgical debridement combined with broad-spectrum intravenous antibiotics; antibiotics alone cannot control the infection because the tissue is devascularized. Oral cephalexin is inadequate for a deep, rapidly spreading infection. Wound culture with observation delays life-saving surgery. Hyperbaric oxygen is at most an adjunct and never a substitute for debridement, and vancomycin alone does not cover the polymicrobial flora of necrotizing fasciitis.', 'Hard', 17, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 30-year-old man presents with a painful, red, swollen area on his right thigh that has grown over 3 days. He has a fever of 38.6 C. Examination shows a 4-cm fluctuant, tender mass with surrounding erythema and warmth. There is no crepitus. What is the most appropriate management?', '["Oral cephalexin alone", "Warm compresses only", "Incision and drainage plus trimethoprim-sulfamethoxazole", "Intravenous vancomycin without drainage", "Topical antibiotics"]'::jsonb, 2, 'A fluctuant, tender abscess requires incision and drainage as the primary treatment, because antibiotics alone penetrate poorly into a walled-off collection. In a patient with systemic features such as fever and a 4-cm abscess, drainage should be combined with an antibiotic active against methicillin-resistant Staphylococcus aureus, such as trimethoprim-sulfamethoxazole. Cephalexin alone does not cover MRSA and cannot drain the collection. Warm compresses alone are inadequate for a large abscess with fever. Intravenous vancomycin without drainage fails to address the collection. Topical antibiotics do not reach deep tissue and are ineffective for abscesses.', 'Medium', 18, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 22-year-old college student presents with 12 hours of high fever, severe headache, neck stiffness, photophobia, and confusion. His temperature is 39.5 C, heart rate 118/min, and blood pressure 110/70 mm Hg. Examination shows nuchal rigidity and a positive Kernig sign, with no focal neurologic deficits and no papilledema. What is the most appropriate management?', '["Perform lumbar puncture and then start antibiotics", "Obtain CT of the head, then lumbar puncture, then antibiotics", "Give dexamethasone alone", "Start ceftriaxone plus vancomycin plus dexamethasone immediately", "Start acyclovir alone"]'::jsonb, 3, 'Bacterial meningitis is a medical emergency, and empiric antibiotics must be given immediately without waiting for imaging or lumbar puncture results. The standard regimen is ceftriaxone plus vancomycin to cover Streptococcus pneumoniae, including resistant strains, and Neisseria meningitidis. Dexamethasone given before or with the first antibiotic dose reduces hearing loss and neurologic sequelae in pneumococcal meningitis. Performing lumbar puncture first delays antibiotics and worsens outcomes. CT before lumbar puncture is unnecessary here because there are no focal deficits or papilledema. Dexamethasone alone and acyclovir alone do not treat bacterial meningitis.', 'Hard', 19, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 40-year-old man presents with fever, severe headache, and neck stiffness for 1 day. On examination he has a right-sided facial droop, weakness of the right arm, and bilateral papilledema. His Glasgow Coma Scale score is 13. Bacterial meningitis is suspected. What is the most appropriate next step before performing a lumbar puncture?', '["Start antibiotics after lumbar puncture", "Perform lumbar puncture immediately", "Give dexamethasone only", "Obtain blood cultures only", "Obtain a CT scan of the head before lumbar puncture"]'::jsonb, 4, 'Lumbar puncture is contraindicated until imaging excludes a mass lesion or raised intracranial pressure when there are focal neurologic deficits, papilledema, or a depressed level of consciousness, because removing cerebrospinal fluid in that setting risks brain herniation. A CT scan of the head should therefore be obtained before lumbar puncture, with antibiotics given beforehand so treatment is not delayed. Performing lumbar puncture immediately in this patient is dangerous. Dexamethasone alone does not treat meningitis, and blood cultures alone are insufficient when meningitis is suspected and cerebrospinal fluid analysis is needed.', 'Medium', 20, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 19-year-old college student is diagnosed with meningococcal meningitis caused by Neisseria meningitidis. His roommate, who shares a dormitory room with him, is asymptomatic. The roommate asks about prevention. What is the most appropriate chemoprophylaxis for this close contact?', '["Rifampin", "Penicillin", "No prophylaxis is needed", "Meningococcal vaccine only", "Amoxicillin"]'::jsonb, 0, 'Close contacts of a patient with invasive meningococcal disease require chemoprophylaxis to eradicate nasopharyngeal carriage and prevent secondary cases. Rifampin is a standard prophylactic agent, as are ciprofloxacin and ceftriaxone. Penicillin does not reliably eradicate nasopharyngeal carriage and is not used for prophylaxis. Withholding prophylaxis is unsafe because household and dormitory contacts have a markedly increased risk of disease. Meningococcal vaccination provides long-term protection but does not act quickly enough to prevent disease in the days after exposure, so it cannot replace chemoprophylaxis. Amoxicillin is ineffective for eradicating carriage.', 'Medium', 21, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 58-year-old man with a history of injection drug use presents with 2 weeks of fever, night sweats, and fatigue. Examination shows a new holosystolic murmur, splinter hemorrhages, and painless erythematous macules on his palms. Blood cultures grow Staphylococcus aureus in 3 of 3 bottles. What is the most appropriate diagnostic test to confirm infective endocarditis?', '["Chest radiograph", "Transthoracic echocardiogram", "Computed tomography of the abdomen", "Cardiac magnetic resonance imaging", "Repeat blood cultures only"]'::jsonb, 1, 'Infective endocarditis is diagnosed using the modified Duke criteria, which require microbiologic evidence and evidence of endocardial involvement. Blood cultures are obtained first, followed by echocardiography to detect vegetations, and transthoracic echocardiography is the appropriate initial imaging study. Chest radiography does not visualize vegetations. CT of the abdomen is useful only if there is concern for embolic complications. Cardiac MRI is not part of the standard diagnostic workup for endocarditis. Repeat blood cultures alone do not establish endocardial involvement, which is required for diagnosis.', 'Medium', 22, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 65-year-old man with a prosthetic aortic valve presents with fever, dyspnea, and a new diastolic murmur. Blood cultures grow Staphylococcus aureus. Transesophageal echocardiography shows a large vegetation on the prosthetic valve with a paravalvular abscess. He has signs of acute heart failure with pulmonary edema. What is the most appropriate management?', '["Oral antibiotics for 6 weeks", "Intravenous antibiotics for 2 weeks", "Intravenous antibiotics for at least 6 weeks plus evaluation for valve surgery", "Anticoagulation alone", "Watchful waiting with repeat echocardiography"]'::jsonb, 2, 'Prosthetic valve endocarditis caused by Staphylococcus aureus requires prolonged intravenous antibiotic therapy for at least 6 weeks, and the development of heart failure is an indication for surgical evaluation because medical therapy alone has high mortality in this setting. Oral antibiotics do not achieve adequate bactericidal concentrations in endocardial vegetations. A 2-week course is far too short for prosthetic valve endocarditis. Anticoagulation alone does not treat infection and may increase the risk of intracranial hemorrhage from embolic phenomena. Watchful waiting is inappropriate in a patient with prosthetic valve infection and new heart failure.', 'Hard', 23, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 45-year-old man with a prosthetic mitral valve is scheduled for a dental extraction in 1 week. He has no drug allergies. He asks whether he needs antibiotics before the procedure. What is the most appropriate prophylaxis?', '["No prophylaxis is needed", "Clindamycin 600 mg orally", "Amoxicillin-clavulanate", "Amoxicillin 2 g orally 30-60 minutes before the procedure", "Intravenous vancomycin"]'::jsonb, 3, 'Antibiotic prophylaxis for infective endocarditis is recommended before dental procedures that involve manipulation of gingival tissue in patients at highest risk, including those with prosthetic heart valves. A single dose of amoxicillin 2 g orally 30 to 60 minutes before the procedure is the standard regimen. No prophylaxis is incorrect for a patient with a prosthetic valve undergoing dental extraction. Clindamycin is an alternative only for patients with penicillin allergy. Amoxicillin-clavulanate is not the recommended prophylactic agent. Vancomycin is reserved for patients unable to take oral medication or with severe penicillin allergy.', 'Medium', 24, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 70-year-old woman is hospitalized after a course of clindamycin for a dental infection. She now has watery diarrhea 8 times per day, lower abdominal cramps, and a fever of 38.5 C. Laboratory studies show a white blood cell count of 17,000/microL and a creatinine level of 1.6 mg/dL. Stool testing is positive for Clostridioides difficile toxin. What is the most appropriate management?', '["Continue clindamycin and add loperamide", "Give loperamide alone", "Start metronidazole", "Send a stool toxin test and wait for the result", "Stop clindamycin and start oral vancomycin"]'::jsonb, 4, 'This presentation is classic for Clostridioides difficile infection following clindamycin exposure, with profuse watery diarrhea, cramping, leukocytosis, and a positive stool toxin assay. The first step is to stop the inciting antibiotic, and oral vancomycin is the preferred treatment for severe disease. Continuing clindamycin would worsen the infection. Loperamide is contraindicated because slowing intestinal transit can precipitate toxic megacolon. Metronidazole is no longer first-line for severe disease because it is less effective than vancomycin. Sending a stool test alone delays treatment in a patient who already has a positive result and severe symptoms.', 'Medium', 25, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 28-year-old man returns from a trip to Mexico with 3 days of bloody diarrhea, fever to 39.0 C, and severe lower abdominal cramps with tenesmus. Stool examination shows many leukocytes and red blood cells. His white blood cell count is 15,000/microL. What is the most appropriate treatment?', '["Empiric ciprofloxacin for suspected Shigella dysentery", "Metronidazole for Entamoeba histolytica", "Supportive care with oral rehydration only", "Loperamide for symptom control", "Oral vancomycin"]'::jsonb, 0, 'Bloody diarrhea with fever and tenesmus after travel, with fecal leukocytes on stool examination, is characteristic of invasive bacterial dysentery, most commonly Shigella. Empiric treatment with a fluoroquinolone such as ciprofloxacin shortens the illness and reduces complications. Entamoeba histolytica typically causes bloody diarrhea without prominent fever and is diagnosed by stool antigen or microscopy showing trophozoites with ingested red blood cells. Supportive care alone is inadequate for invasive dysentery with systemic features. Loperamide is contraindicated in dysentery because it can worsen the infection. Oral vancomycin is used for Clostridioides difficile, not for Shigella.', 'Medium', 26, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'An 8-year-old boy presents with 2 days of bloody diarrhea and crampy abdominal pain after eating an undercooked hamburger at a family barbecue. He is afebrile with mild dehydration. Laboratory studies show a normal white blood cell count and a creatinine level of 0.8 mg/dL. Stool culture is pending. What is the most appropriate management?', '["Start ciprofloxacin", "Supportive care with intravenous fluids and avoid antibiotics", "Start azithromycin", "Start oral vancomycin", "Give loperamide"]'::jsonb, 1, 'Bloody diarrhea in a child after eating undercooked ground beef is classic for enterohemorrhagic Escherichia coli O157:H7, which produces Shiga toxin. Antibiotics should be avoided because they increase the risk of hemolytic uremic syndrome by promoting toxin release, and antimotility agents such as loperamide are also contraindicated. The correct management is supportive care with intravenous fluids and close monitoring for hemolytic uremic syndrome. Ciprofloxacin and azithromycin are both inappropriate because antibiotics worsen outcomes in this infection. Oral vancomycin is used for Clostridioides difficile infection, not for enterohemorrhagic E. coli.', 'Medium', 27, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 24-year-old man presents with 3 days of dysuria and a thick yellow urethral discharge. Gram stain of the discharge shows gram-negative intracellular diplococci within polymorphonuclear leukocytes. Nucleic acid amplification testing for chlamydia is pending. What is the most appropriate treatment?', '["Azithromycin alone", "Doxycycline alone", "Ceftriaxone plus doxycycline", "Penicillin G", "Metronidazole"]'::jsonb, 2, 'Urethritis with purulent discharge and gram-negative intracellular diplococci on Gram stain is diagnostic of gonorrhea, and current guidelines recommend treatment with a single intramuscular dose of ceftriaxone plus doxycycline to cover coexistent chlamydia, which is frequently present and often asymptomatic. Azithromycin alone is no longer adequate because of rising resistance in Neisseria gonorrhoeae. Doxycycline alone does not treat gonorrhea. Penicillin G is ineffective because of widespread resistance in gonococcal isolates. Metronidazole treats trichomoniasis and bacterial vaginosis, not gonococcal urethritis, so it would leave the infection untreated.', 'Medium', 28, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 32-year-old man presents with a painless ulcer on the glans penis that has been present for 2 weeks. Examination shows a single, firm, clean-based ulcer with raised borders and nontender inguinal lymphadenopathy. Rapid plasma reagin testing is positive at a titer of 1:64. What is the most appropriate treatment?', '["Acyclovir", "Doxycycline", "Ceftriaxone", "Benzathine penicillin G intramuscularly", "Azithromycin"]'::jsonb, 3, 'A painless genital ulcer with firm, nontender inguinal lymphadenopathy is classic for a primary syphilis chancre, and the treatment of choice is a single intramuscular dose of benzathine penicillin G. Darkfield microscopy or serologic testing confirms the diagnosis, but penicillin remains first-line therapy. Acyclovir treats herpes simplex virus, which causes painful vesicular ulcers rather than a single painless chancre. Doxycycline is an alternative only in penicillin-allergic patients. Ceftriaxone is used for gonorrhea, not syphilis. Azithromycin is not recommended for syphilis because of resistance.', 'Easy', 29, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 45-year-old woman with HIV infection presents with a diffuse maculopapular rash involving the palms and soles, generalized lymphadenopathy, and 1 week of headache and confusion. Rapid plasma reagin is positive at a titer of 1:128. Cerebrospinal fluid analysis shows a lymphocytic pleocytosis with an elevated protein level and a positive Venereal Disease Research Laboratory test. What is the most appropriate treatment?', '["Benzathine penicillin G intramuscularly", "Doxycycline", "Ceftriaxone", "Azithromycin", "Aqueous penicillin G intravenously for 10-14 days"]'::jsonb, 4, 'Neurosyphilis requires aqueous crystalline penicillin G given intravenously for 10 to 14 days, because benzathine penicillin G does not cross the blood-brain barrier in adequate concentrations. A single intramuscular dose of benzathine penicillin treats early syphilis without central nervous system involvement but is inadequate for neurosyphilis. Doxycycline is an alternative for early syphilis in penicillin-allergic patients but is not used for neurosyphilis. Ceftriaxone has some activity against Treponema pallidum but is not the treatment of choice for neurosyphilis. Azithromycin is not recommended because of resistance and poor central nervous system penetration.', 'Hard', 30, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 28-year-old man presents with 5 days of fever, sore throat, diffuse lymphadenopathy, and a maculopapular rash. He reports unprotected sex with a new partner 3 weeks ago. He is hemodynamically stable with no meningeal signs. Which of the following is the most appropriate initial test?', '["HIV RNA viral load", "Fourth-generation HIV antigen/antibody immunoassay", "HIV Western blot", "Absolute CD4 count", "HIV genotypic resistance testing"]'::jsonb, 1, 'This presentation is acute retroviral syndrome, which occurs 2 to 4 weeks after HIV exposure with fever, pharyngitis, lymphadenopathy, and rash. The fourth-generation antigen/antibody immunoassay is the recommended initial screening test because it detects both p24 antigen and HIV antibodies, identifying infection earlier than antibody-only tests. HIV RNA viral load is not used for routine screening because of cost and false-positive results; it is used for confirmation and monitoring. Western blot is no longer the confirmatory standard and has been replaced by differentiation immunoassays. CD4 count monitors disease progression rather than diagnosing infection. Genotypic resistance testing guides antiretroviral selection after diagnosis, not initial testing.', 'Medium', 31, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 34-year-old man is newly diagnosed with HIV infection. His CD4 count is 350 cells/uL and his HIV viral load is 80,000 copies/mL. He has no opportunistic infections, normal renal function, and is negative for HLA-B*5701. Which of the following is the most appropriate initial antiretroviral regimen?', '["Bictegravir-tenofovir alafenamide-emtricitabine", "Efavirenz-tenofovir-emtricitabine", "Ritonavir-boosted darunavir plus two nucleoside reverse transcriptase inhibitors", "Zidovudine monotherapy", "Defer antiretroviral therapy until the CD4 count falls below 200 cells/uL"]'::jsonb, 0, 'Integrase strand transfer inhibitor-based regimens are first-line for initial HIV therapy per HHS guidelines because of high efficacy, a high barrier to resistance, and a favorable side effect profile. Bictegravir-tenofovir alafenamide-emtricitabine is a once-daily single-tablet regimen. Efavirenz-based therapy is an older alternative with central nervous system side effects including vivid dreams and dizziness. Protease inhibitor-based regimens are effective but carry more drug interactions and metabolic effects. Zidovudine monotherapy is obsolete and rapidly selects for resistance. Antiretroviral therapy should be started immediately regardless of CD4 count, as shown by the START trial, reducing disease progression and transmission.', 'Medium', 32, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 42-year-old man with HIV infection has a CD4 count of 150 cells/uL. He is taking antiretroviral therapy and has no prior opportunistic infections and no drug allergies. Which of the following prophylaxis is most appropriate for this patient?', '["Azithromycin weekly", "Fluconazole daily", "Trimethoprim-sulfamethoxazole daily", "Isoniazid daily", "No prophylaxis is needed while on antiretroviral therapy"]'::jsonb, 2, 'Pneumocystis jirovecii pneumonia prophylaxis is indicated when the CD4 count falls below 200 cells/uL, and trimethoprim-sulfamethoxazole is the first-line agent. It also provides protection against toxoplasmosis. Azithromycin is used for Mycobacterium avium complex prophylaxis, which is indicated only when the CD4 count is below 50 cells/uL. Fluconazole is not routinely given for cryptococcal prophylaxis at this CD4 count. Isoniazid is used for latent tuberculosis infection, which is a separate indication requiring a positive screening test. Antiretroviral therapy alone does not replace prophylaxis until the CD4 count rises above 200 cells/uL for at least 3 months.', 'Medium', 33, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 38-year-old man with HIV infection and a CD4 count of 80 cells/uL presents with 2 weeks of progressive headache, confusion, and right-sided weakness. He is afebrile. MRI of the brain shows multiple ring-enhancing lesions in the basal ganglia. Serum Toxoplasma IgG is positive. Which of the following is the most likely diagnosis?', '["Primary central nervous system lymphoma", "Cryptococcal meningitis", "Progressive multifocal leukoencephalopathy", "Cerebral toxoplasmosis", "Cytomegalovirus encephalitis"]'::jsonb, 3, 'Cerebral toxoplasmosis is the most common cause of focal brain lesions in advanced AIDS when the CD4 count is below 100 cells/uL. It typically produces multiple ring-enhancing lesions in the basal ganglia with positive Toxoplasma IgG, reflecting reactivation of latent infection. Primary central nervous system lymphoma usually causes a single lesion and is associated with Epstein-Barr virus DNA in the cerebrospinal fluid. Cryptococcal meningitis causes meningitis with headache and elevated intracranial pressure, not focal ring-enhancing lesions. Progressive multifocal leukoencephalopathy causes non-enhancing white matter lesions without mass effect. Cytomegalovirus encephalitis causes periventricular disease and ventriculitis rather than basal ganglia ring-enhancing lesions.', 'Hard', 34, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 68-year-old woman with chronic obstructive pulmonary disease presents with 2 days of fever to 39.2 C, myalgias, dry cough, and sore throat during peak influenza season. A rapid influenza antigen test is positive. Which of the following is the most appropriate treatment?', '["Amantadine", "Supportive care only", "Amoxicillin-clavulanate", "Inhaled zanamivir", "Oseltamivir"]'::jsonb, 4, 'Oseltamivir is a neuraminidase inhibitor that is most effective when started within 48 hours of symptom onset, reducing illness duration and complications. It is recommended for high-risk patients, including those older than 65 years and those with chronic lung disease, even beyond 48 hours. Amantadine is no longer recommended because of widespread resistance among circulating influenza strains. Supportive care alone is insufficient in a high-risk patient who benefits from antiviral therapy. Antibiotics are indicated only if bacterial superinfection is present. Inhaled zanamivir is contraindicated in patients with chronic obstructive pulmonary disease or asthma because it can cause bronchospasm.', 'Medium', 35, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 29-year-old woman at 24 weeks of gestation presents for routine prenatal care. She has not received an influenza vaccine this season and is otherwise healthy. Which of the following is the most appropriate recommendation?', '["Inactivated influenza vaccine now", "Live attenuated influenza vaccine now", "Oseltamivir prophylaxis instead of vaccination", "Defer vaccination until after delivery", "Influenza vaccine only if she develops symptoms"]'::jsonb, 0, 'Inactivated influenza vaccine is recommended for all pregnant women during any trimester because pregnancy increases the risk of severe influenza, hospitalization, and complications. Maternal vaccination also protects the infant through transplacental antibody transfer during the first months of life. The live attenuated influenza vaccine is contraindicated in pregnancy because it contains live virus. Oseltamivir is used for treatment or post-exposure prophylaxis and is not a substitute for vaccination. Deferring vaccination until after delivery leaves the mother unprotected during a high-risk period. Vaccination is preventive and is not given after symptoms develop.', 'Easy', 36, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 72-year-old man recovering from influenza returns on day 7 with worsening fever, productive cough with purulent sputum, and pleuritic chest pain. Chest radiograph shows a new lobar consolidation. Which of the following is the most likely diagnosis?', '["Influenza pneumonitis", "Secondary bacterial pneumonia", "Pulmonary embolism", "Acute respiratory distress syndrome", "Tuberculosis reactivation"]'::jsonb, 1, 'A biphasic course with initial improvement followed by worsening fever, purulent sputum, and lobar consolidation is classic for secondary bacterial pneumonia after influenza. Influenza damages airway epithelium and impairs mucociliary clearance, predisposing to infection with Staphylococcus aureus, Streptococcus pneumoniae, and Haemophilus influenzae. Primary influenza pneumonitis presents early with diffuse infiltrates and hypoxemia rather than a delayed lobar pattern. Pulmonary embolism causes dyspnea and pleuritic pain but not purulent sputum or consolidation. Acute respiratory distress syndrome causes diffuse bilateral opacities. Tuberculosis reactivation is subacute with upper lobe cavitation and night sweats.', 'Medium', 37, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 26-year-old man presents with fatigue, jaundice, dark urine, alanine aminotransferase of 1,200 U/L, and aspartate aminotransferase of 980 U/L. Serologic testing shows hepatitis B surface antigen positive, anti-hepatitis B surface antibody negative, anti-hepatitis B core IgM positive, and hepatitis B e antigen positive. Which of the following is the most likely interpretation?', '["Chronic hepatitis B infection", "Prior hepatitis B vaccination", "Acute hepatitis B infection", "Resolved hepatitis B infection", "Hepatitis B window period"]'::jsonb, 2, 'Acute hepatitis B infection is diagnosed by positive hepatitis B surface antigen with positive anti-hepatitis B core IgM, which indicates recent infection. Positive hepatitis B e antigen reflects active viral replication, and markedly elevated transaminases with jaundice are typical of acute hepatitis. Chronic hepatitis B infection shows anti-hepatitis B core IgG rather than IgM. Prior vaccination produces anti-hepatitis B surface antibody alone with negative surface antigen and core antibody. Resolved infection shows anti-hepatitis B surface antibody and anti-hepatitis B core IgG with negative surface antigen. The window period is characterized by negative surface antigen with positive anti-hepatitis B core IgM.', 'Medium', 38, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 45-year-old man with chronic hepatitis B infection is hepatitis B e antigen positive with hepatitis B virus DNA of 250,000 IU/mL and alanine aminotransferase of 120 U/L, twice the upper limit of normal. He has no evidence of cirrhosis. Which of the following is the most appropriate treatment?', '["Pegylated interferon only", "Lamivudine monotherapy", "Observation without treatment", "Tenofovir or entecavir", "Hepatitis B immune globulin"]'::jsonb, 3, 'Chronic hepatitis B with high viral load and elevated alanine aminotransferase meets criteria for antiviral treatment to prevent progression to cirrhosis and hepatocellular carcinoma. Tenofovir or entecavir are first-line nucleoside and nucleotide analogues because they are potent and have a high barrier to resistance. Pegylated interferon is an alternative with more side effects and a lower response rate, so it is not first-line. Lamivudine has high rates of resistance and is no longer recommended. Observation is inappropriate with active viral replication and liver inflammation. Hepatitis B immune globulin is used for post-exposure prophylaxis, not for treatment of chronic infection.', 'Hard', 39, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A newborn is delivered vaginally to a mother known to be hepatitis B surface antigen positive. Which of the following is the most appropriate immediate management for the newborn?', '["Hepatitis B vaccine at 2 months of age", "No intervention, because maternal antibodies protect the infant", "Hepatitis B immune globulin alone", "Hepatitis B vaccine alone within 12 hours of birth", "Hepatitis B immune globulin plus hepatitis B vaccine within 12 hours of birth"]'::jsonb, 4, 'Infants born to hepatitis B surface antigen-positive mothers require hepatitis B immune globulin plus the first dose of hepatitis B vaccine within 12 hours of birth. This combination prevents perinatal transmission in approximately 95 percent of cases. Waiting until 2 months of age is far too late, since perinatal infection usually occurs during delivery. Maternal antibodies do not protect the infant, and perinatal infection leads to chronic hepatitis B in about 90 percent of cases. Immune globulin alone provides only temporary passive immunity and is insufficient. Vaccine alone without immune globulin leaves a window of vulnerability before active immunity develops.', 'Medium', 40, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 58-year-old man born in 1968 presents for a routine visit. He is healthy, has no history of injection drug use or blood transfusion, and has no known liver disease. Which of the following is the most appropriate hepatitis C screening for this patient?', '["One-time hepatitis C antibody screening", "No screening without risk factors", "Annual hepatitis C antibody screening", "Hepatitis C RNA testing only", "Liver biopsy to screen for hepatitis C"]'::jsonb, 0, 'The United States Preventive Services Task Force and the Centers for Disease Control and Prevention recommend one-time hepatitis C antibody screening for all adults aged 18 to 79 years, regardless of risk factors. Most chronic hepatitis C infection is asymptomatic, and many infected persons have no identifiable risk factor, so risk-based screening misses cases. Untreated infection can progress silently to cirrhosis and hepatocellular carcinoma, yet it is now curable. Annual screening is reserved for persons with ongoing risk such as injection drug use. Hepatitis C RNA is the confirmatory test after a positive antibody, not the screening test. Liver biopsy is invasive and is not a screening tool.', 'Easy', 41, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 40-year-old woman has a positive hepatitis C antibody on routine screening. Her liver function tests are normal. Which of the following is the most appropriate next step?', '["Start direct-acting antiviral therapy immediately", "Hepatitis C RNA testing", "Reassure the patient, because the antibody indicates resolved infection", "Liver biopsy", "Repeat hepatitis C antibody testing in 6 months"]'::jsonb, 1, 'A positive hepatitis C antibody indicates exposure to the virus, not necessarily active infection, because approximately 25 percent of infected persons clear the virus spontaneously. Hepatitis C RNA testing confirms active viremia and is required before starting treatment. Starting direct-acting antiviral therapy without confirming viremia would treat people who have already cleared the infection. Antibody testing alone cannot distinguish resolved from chronic infection. Liver biopsy is not needed to confirm infection and is reserved for staging liver disease. Repeating the antibody test adds no information because the antibody persists after clearance.', 'Medium', 42, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 52-year-old man has chronic hepatitis C, genotype 1a, with hepatitis C virus RNA of 2 million IU/mL, no cirrhosis, and normal renal function. He has never received treatment. Which of the following is the most appropriate treatment?', '["Pegylated interferon plus ribavirin for 48 weeks", "Sofosbuvir plus ribavirin alone", "Glecaprevir-pibrentasvir or sofosbuvir-velpatasvir for 8 to 12 weeks", "Observation, with treatment only if cirrhosis develops", "Liver transplant evaluation"]'::jsonb, 2, 'Pangenotypic direct-acting antivirals such as glecaprevir-pibrentasvir or sofosbuvir-velpatasvir are first-line therapy for chronic hepatitis C, curing more than 95 percent of patients in 8 to 12 weeks with minimal side effects. Pegylated interferon plus ribavirin is obsolete, poorly tolerated, and has much lower cure rates. Sofosbuvir plus ribavirin alone is inadequate for genotype 1a infection. Deferring treatment allows fibrosis to progress and permits ongoing transmission. Liver transplant evaluation is reserved for decompensated cirrhosis or hepatocellular carcinoma, not uncomplicated chronic hepatitis C without cirrhosis.', 'Hard', 43, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 55-year-old man presents with 3 days of fever, confusion, and a new-onset seizure. Magnetic resonance imaging of the brain shows temporal lobe hyperintensity. Cerebrospinal fluid shows lymphocytic pleocytosis with elevated red blood cells and normal glucose. Which of the following is the most appropriate immediate management?', '["Intravenous ceftriaxone alone", "Oral valacyclovir and discharge home", "Repeat lumbar puncture in 1 week", "Intravenous acyclovir immediately", "High-dose corticosteroids alone"]'::jsonb, 3, 'This presentation is classic for herpes simplex virus encephalitis, with fever, altered mental status, seizures, and temporal lobe involvement on magnetic resonance imaging. Cerebrospinal fluid typically shows lymphocytic pleocytosis with red blood cells and normal glucose. Intravenous acyclovir must be started immediately because delay increases mortality and long-term neurologic sequelae. Ceftriaxone alone does not cover herpes simplex virus. Oral valacyclovir has inadequate central nervous system penetration for encephalitis. Repeating lumbar puncture delays treatment. Corticosteroids alone do not treat herpes simplex virus and are at most adjunctive therapy.', 'Medium', 44, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 48-year-old woman presents with fever, headache, and confusion. Cerebrospinal fluid shows lymphocytic pleocytosis, elevated protein, normal glucose, and a negative Gram stain. Which of the following is the most sensitive test to confirm herpes simplex virus encephalitis?', '["Serum herpes simplex virus IgM", "Brain biopsy", "Electroencephalography", "Computed tomography of the head with contrast", "Cerebrospinal fluid herpes simplex virus polymerase chain reaction"]'::jsonb, 4, 'Cerebrospinal fluid herpes simplex virus polymerase chain reaction is the gold standard test for herpes simplex encephalitis, with high sensitivity and specificity, and its results guide the duration of acyclovir therapy. Serum herpes simplex virus IgM cannot distinguish acute central nervous system infection from prior exposure. Brain biopsy is invasive and is rarely needed now that polymerase chain reaction testing is available. Electroencephalography may show temporal lobe slowing but is nonspecific. Computed tomography of the head is insensitive in early encephalitis and is mainly used to exclude a mass lesion before lumbar puncture.', 'Hard', 45, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 72-year-old man presents with a painful vesicular rash in the ophthalmic division of the trigeminal nerve, along with eye redness and photophobia. Which of the following is the most appropriate management?', '["Oral valacyclovir plus urgent ophthalmology referral", "Topical antibiotics alone", "Reassurance, because the rash resolves without treatment", "Oral corticosteroids alone", "Intravenous acyclovir only if immunocompromised"]'::jsonb, 0, 'Herpes zoster ophthalmicus involves the ophthalmic division of the trigeminal nerve and risks keratitis, uveitis, and permanent vision loss. Oral valacyclovir started within 72 hours of rash onset reduces the severity and duration of disease, and urgent ophthalmology evaluation is required to assess for ocular involvement. Topical antibiotics treat bacterial superinfection only and do not address the viral infection. Reassurance is unsafe because untreated zoster ophthalmicus can cause irreversible vision loss. Corticosteroids alone do not treat the virus. Intravenous acyclovir is reserved for immunocompromised patients or severe disseminated disease.', 'Medium', 46, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 45-year-old man with HIV infection and a CD4 count of 40 cells/uL presents with painless progressive vision loss in the right eye and floaters. There is no eye pain or redness. Fundoscopy shows hemorrhagic necrotizing retinitis with a granular border. Which of the following is the most likely diagnosis?', '["Toxoplasma retinochoroiditis", "Cytomegalovirus retinitis", "Human immunodeficiency virus retinopathy", "Acute retinal necrosis from herpes simplex virus", "Syphilitic uveitis"]'::jsonb, 1, 'Cytomegalovirus retinitis is the most common opportunistic ocular infection in advanced AIDS when the CD4 count is below 50 cells/uL. It causes painless progressive vision loss with characteristic hemorrhagic necrotizing retinitis and a granular border. Toxoplasma retinochoroiditis typically presents with vitritis and a focal white retinal lesion. Human immunodeficiency virus retinopathy causes cotton-wool spots but does not cause vision loss. Acute retinal necrosis from herpes simplex virus is painful with rapid progression and peripheral retinal necrosis. Syphilitic uveitis usually presents with eye pain, redness, and other systemic features of syphilis.', 'Hard', 47, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 19-year-old college student presents with 1 week of fever, severe sore throat, posterior cervical lymphadenopathy, fatigue, and splenomegaly. Complete blood count shows atypical lymphocytes of 15 percent. Which of the following is the most appropriate initial test?', '["Human immunodeficiency virus antigen/antibody test", "Throat culture for Streptococcus", "Heterophile antibody test (Monospot)", "Cytomegalovirus IgM", "Bone marrow biopsy"]'::jsonb, 2, 'This presentation is classic for infectious mononucleosis caused by Epstein-Barr virus, with fever, severe pharyngitis, posterior cervical lymphadenopathy, splenomegaly, and atypical lymphocytosis. The heterophile antibody test, known as the Monospot test, is the rapid initial test and is highly specific in adolescents and adults. Human immunodeficiency virus testing is reasonable but acute HIV infection is less likely given this classic triad. Throat culture misses Epstein-Barr virus, and atypical lymphocytes point away from streptococcal pharyngitis. Cytomegalovirus IgM is used when the heterophile test is negative. Bone marrow biopsy is unnecessary for this diagnosis.', 'Easy', 48, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 20-year-old man diagnosed with infectious mononucleosis 2 weeks ago presents with sudden severe left upper quadrant pain, dizziness, and hypotension after a minor bump to his abdomen. Which of the following is the most likely diagnosis?', '["Appendicitis", "Hepatitis with liver failure", "Myocarditis", "Splenic rupture", "Peptic ulcer perforation"]'::jsonb, 3, 'Epstein-Barr virus causes splenomegaly in approximately half of cases, and splenic rupture is a rare but life-threatening complication, classically occurring 2 to 3 weeks into the illness. It presents with acute left upper quadrant pain, hypotension, and Kehr sign after even minor abdominal trauma. Appendicitis causes right lower quadrant pain rather than left upper quadrant pain. Hepatitis causes right upper quadrant pain and jaundice without hypotension. Myocarditis causes chest pain and dyspnea. Peptic ulcer perforation causes epigastric pain with peritoneal signs, not left upper quadrant pain with hypotension after minor trauma.', 'Hard', 49, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 25-year-old woman presents with 2 weeks of fever, fatigue, sore throat, and lymphadenopathy. Her blood smear shows atypical lymphocytes, but the heterophile antibody test is negative on two occasions. Which of the following is the most likely cause?', '["Streptococcal pharyngitis", "Acute human immunodeficiency virus infection", "Toxoplasmosis", "Adenovirus infection", "Cytomegalovirus infection"]'::jsonb, 4, 'Cytomegalovirus is the most common cause of heterophile-negative mononucleosis-like syndrome, producing fever, fatigue, lymphadenopathy, and atypical lymphocytes, often with mild hepatitis. Streptococcal pharyngitis lacks atypical lymphocytes and the systemic features of mononucleosis. Acute human immunodeficiency virus infection can mimic mononucleosis but is less common than cytomegalovirus in heterophile-negative cases and usually has a rash. Toxoplasmosis typically causes painless lymphadenopathy without pharyngitis. Adenovirus causes respiratory symptoms and does not produce a mononucleosis-like syndrome with atypical lymphocytes. Testing with cytomegalovirus IgM or polymerase chain reaction confirms the diagnosis, and management is usually supportive in immunocompetent patients, with avoidance of contact sports if splenomegaly is present.', 'Medium', 50, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 4-year-old unvaccinated boy presents with 4 days of fever, cough, coryza, and conjunctivitis. Examination shows white spots on the buccal mucosa, and he now has an erythematous maculopapular rash starting on the face and spreading downward. Which of the following is the most likely diagnosis?', '["Measles", "Rubella", "Scarlet fever", "Roseola infantum", "Kawasaki disease"]'::jsonb, 0, 'Measles presents with a prodrome of fever, cough, coryza, and conjunctivitis, known as the three Cs, followed by Koplik spots on the buccal mucosa and then a cephalocaudal maculopapular rash. Rubella has a milder course with postauricular lymphadenopathy and no Koplik spots. Scarlet fever causes a sandpaper rash with strawberry tongue from streptococcal infection. Roseola infantum causes high fever followed by a rash after defervescence. Kawasaki disease causes prolonged fever with conjunctivitis, mucosal changes, extremity edema, and risk of coronary artery aneurysms, but it does not cause Koplik spots.', 'Medium', 51, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 21-year-old unvaccinated college student presents with 3 days of fever and bilateral parotid swelling. He now has severe testicular pain and swelling. Which of the following is the most likely diagnosis?', '["Bacterial parotitis", "Mumps", "Epstein-Barr virus infection", "Influenza", "Cytomegalovirus infection"]'::jsonb, 1, 'Mumps classically causes parotitis followed by orchitis in postpubertal males, a well-known complication that can lead to testicular atrophy. Bacterial parotitis is usually unilateral with purulent discharge from the parotid duct. Epstein-Barr virus infection causes pharyngitis and lymphadenopathy but not parotitis or orchitis. Influenza causes respiratory symptoms without parotid swelling. Cytomegalovirus rarely causes parotitis and does not cause orchitis. Mumps is prevented by the measles-mumps-rubella vaccine, and this patient is unvaccinated. Orchitis typically develops 4 to 7 days after parotitis and may cause testicular atrophy, so supportive care with analgesia and scrotal support is the mainstay of treatment. Isolation for 5 days after the onset of parotitis prevents further spread.', 'Medium', 52, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 26-year-old woman at 8 weeks of gestation was exposed to a child with rubella and now has mild fever, a pink maculopapular rash, and postauricular lymphadenopathy. She never received the measles-mumps-rubella vaccine. Which of the following is the most appropriate next step?', '["Administer measles-mumps-rubella vaccine immediately", "Terminate the pregnancy", "Check rubella IgM and IgG to confirm infection", "Reassure the patient, because rubella is harmless in pregnancy", "Administer rubella immune globulin to prevent infection"]'::jsonb, 2, 'Infection should be confirmed with rubella IgM and IgG testing, since the risk of congenital rubella syndrome depends on the timing of infection and is highest in the first trimester. Congenital rubella can cause cataracts, deafness, and cardiac defects. The measles-mumps-rubella vaccine is a live vaccine and is contraindicated during pregnancy. Termination is a decision made only after confirmed diagnosis and counseling, not the next step. Rubella is not harmless in pregnancy because it is teratogenic. Rubella immune globulin does not reliably prevent fetal infection after maternal exposure.', 'Easy', 53, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 70-year-old man with diabetes and chronic obstructive pulmonary disease has day 3 of mild COVID-19 with fever and cough, no hypoxia, and oxygen saturation of 96 percent on room air. A rapid antigen test is positive. Which of the following is the most appropriate treatment?', '["Dexamethasone", "Remdesivir alone as an outpatient", "Supportive care only", "Nirmatrelvir-ritonavir (Paxlovid) within 5 days of symptom onset", "Azithromycin"]'::jsonb, 3, 'High-risk outpatients with mild to moderate COVID-19 should receive nirmatrelvir-ritonavir within 5 days of symptom onset, which reduces hospitalization and death. Dexamethasone is reserved for hospitalized patients requiring supplemental oxygen and can worsen early viral replication if given too soon. Remdesivir is given intravenously and is used mainly for hospitalized patients or as a 3-day outpatient course, making it less practical as first-line therapy here. Supportive care alone misses the treatment window in a high-risk patient with diabetes and chronic lung disease. Azithromycin has no antiviral activity against SARS-CoV-2.', 'Hard', 54, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 65-year-old woman is hospitalized with COVID-19 and is on high-flow nasal cannula with oxygen saturation of 88 percent and an elevated C-reactive protein level. Which of the following is the most appropriate treatment?', '["Nirmatrelvir-ritonavir alone", "Hydroxychloroquine", "Ivermectin", "Azithromycin plus ceftriaxone", "Dexamethasone plus remdesivir"]'::jsonb, 4, 'Hospitalized patients requiring high-flow oxygen benefit from dexamethasone, which reduces mortality in oxygen-requiring COVID-19, combined with remdesivir, which shortens recovery time. Nirmatrelvir-ritonavir is indicated for early outpatient disease, not severe hospitalized disease. Hydroxychloroquine showed no benefit in randomized trials and is not recommended. Ivermectin also showed no benefit in trials and is not recommended. Antibiotics such as azithromycin and ceftriaxone are indicated only if bacterial superinfection is suspected, which is not described here. The RECOVERY trial showed dexamethasone reduced mortality in patients requiring oxygen, and remdesivir shortens time to recovery. Baricitinib or tocilizumab may be added for patients with rapidly worsening inflammation despite steroids.', 'Hard', 55, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 78-year-old nursing home resident who is otherwise healthy asks about prevention of COVID-19. Which of the following is the most appropriate recommendation?', '["Updated COVID-19 vaccination", "Daily nirmatrelvir-ritonavir prophylaxis", "Avoid vaccination, because natural immunity is sufficient", "Mask use only, because vaccine is not needed at this age", "Monthly remdesivir infusions"]'::jsonb, 0, 'Updated COVID-19 vaccination is recommended for older adults, especially those living in congregate settings such as nursing homes, because it reduces severe disease, hospitalization, and death. Antivirals such as nirmatrelvir-ritonavir are treatments for acute infection, not daily prophylaxis. Natural immunity wanes over time and is less reliable than vaccination. Masks provide additional protection but do not replace vaccination. Remdesivir is an intravenous treatment given for active infection, not a monthly preventive infusion. Vaccination also reduces the risk of long COVID and protects household contacts. The vaccine should be given even to those with prior infection, since hybrid immunity provides the strongest protection.', 'Easy', 56, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 24-year-old woman presents with 2 days of fever, severe headache, neck stiffness, and photophobia. She is alert and oriented with no focal neurologic deficits. Cerebrospinal fluid shows a white blood cell count of 150 with 90 percent lymphocytes, mildly elevated protein, normal glucose, and a negative Gram stain. Which of the following is the most likely diagnosis?', '["Bacterial meningitis", "Viral (enteroviral) meningitis", "Subarachnoid hemorrhage", "Herpes simplex encephalitis", "Tuberculous meningitis"]'::jsonb, 1, 'Viral meningitis, most commonly caused by enteroviruses, presents with fever, headache, neck stiffness, and photophobia in an alert patient. Cerebrospinal fluid shows lymphocytic pleocytosis with normal glucose and a negative Gram stain. Bacterial meningitis shows neutrophilic pleocytosis, low glucose, high protein, and altered mental status. Subarachnoid hemorrhage causes bloody cerebrospinal fluid and a thunderclap headache. Herpes simplex encephalitis causes altered mental status, seizures, and temporal lobe abnormalities. Tuberculous meningitis is subacute with very low glucose, markedly elevated protein, and a lymphocytic pleocytosis over weeks.', 'Medium', 57, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 60-year-old man presents with fever, confusion, headache, and neck stiffness. Cerebrospinal fluid shows neutrophilic pleocytosis and low glucose. Empiric therapy with vancomycin and ceftriaxone has been started. Which of the following additional agents should be added until herpes simplex virus encephalitis is excluded?', '["Amphotericin B", "Metronidazole", "Intravenous acyclovir", "Doxycycline", "Oseltamivir"]'::jsonb, 2, 'Herpes simplex virus encephalitis can mimic bacterial meningitis and is fatal if missed, so empiric intravenous acyclovir is added to antibacterial coverage whenever encephalitis cannot be excluded. Amphotericin B is used for fungal meningitis, which is not suggested here. Metronidazole covers anaerobic organisms in brain abscess. Doxycycline is used for rickettsial disease or Lyme disease. Oseltamivir treats influenza and has no activity against herpes simplex virus. Early acyclovir is critical because delayed treatment increases mortality and long-term neurologic disability. Treatment should not wait for polymerase chain reaction results, and acyclovir is continued for 14 to 21 days if herpes simplex encephalitis is confirmed.', 'Medium', 58, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'An 8-year-old boy who had varicella 1 week ago now presents with ataxia, vomiting, headache, and drowsiness. Computed tomography of the head is normal. Which of the following is the most likely diagnosis?', '["Reye syndrome", "Bacterial meningitis", "Varicella encephalitis", "Acute cerebellar ataxia from varicella", "Subdural hematoma"]'::jsonb, 3, 'Acute cerebellar ataxia is the most common neurologic complication of varicella, typically occurring about 1 week after the rash appears. It presents with ataxia, vomiting, headache, and drowsiness, and it usually resolves without sequelae. Varicella encephalitis causes more profound altered mental status and seizures. Reye syndrome follows aspirin use in children with viral illness and is characterized by hepatic dysfunction and hypoglycemia. Bacterial meningitis presents with fever, neck stiffness, and neutrophilic cerebrospinal fluid. Subdural hematoma follows head trauma and causes focal neurologic deficits.', 'Medium', 59, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 30-year-old immunocompromised man receiving chemotherapy presents with fever, headache, and confusion. Cerebrospinal fluid shows lymphocytic pleocytosis, and magnetic resonance imaging shows periventricular enhancement. Which of the following is the most likely diagnosis?', '["Cryptococcal meningitis", "Bacterial meningitis", "Tuberculous meningitis", "Progressive multifocal leukoencephalopathy", "Cytomegalovirus encephalitis"]'::jsonb, 4, 'Cytomegalovirus encephalitis occurs in immunocompromised patients and causes periventricular disease, ventriculitis, and encephalopathy with lymphocytic pleocytosis on cerebrospinal fluid analysis. Cryptococcal meningitis causes headache with elevated intracranial pressure and a positive cryptococcal antigen, but not periventricular enhancement. Bacterial meningitis shows neutrophilic pleocytosis with low glucose. Tuberculous meningitis is subacute with basal meningeal enhancement and very low glucose. Progressive multifocal leukoencephalopathy causes non-enhancing white matter lesions without cerebrospinal fluid pleocytosis. Diagnosis of cytomegalovirus encephalitis is confirmed by cytomegalovirus polymerase chain reaction in cerebrospinal fluid, and treatment is intravenous ganciclovir with or without foscarnet, along with optimization of antiretroviral therapy when applicable.', 'Hard', 60, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 34-year-old man who recently immigrated from India presents with a 2-month history of productive cough, hemoptysis, night sweats, and 8 kg of weight loss. He has low-grade fever and appears cachectic, with crackles over the right upper lung field. Chest X-ray shows a right upper lobe cavitary infiltrate. Sputum acid-fast bacilli (AFB) smear is positive. What is the most appropriate next step in management?', '["Start isoniazid monotherapy for 9 months", "Start four-drug RIPE therapy (rifampin, isoniazid, pyrazinamide, ethambutol) and send sputum for culture and nucleic acid amplification testing", "Start broad-spectrum antibiotics for community-acquired pneumonia", "Order bronchoscopy with transbronchial biopsy", "Begin prednisone to reduce cavitary inflammation"]'::jsonb, 1, 'A positive AFB smear with a cavitary upper-lobe lesion is highly suggestive of active pulmonary tuberculosis, and treatment should not wait for culture results; empiric four-drug RIPE therapy (rifampin, isoniazid, pyrazinamide, ethambutol) is started while sputum is sent for culture and nucleic acid amplification testing to confirm the organism and detect rifampin resistance. Isoniazid alone is inadequate for active disease and promotes resistance. Community-acquired pneumonia does not explain chronic cavitary disease with hemoptysis and night sweats. Bronchoscopy is reserved for smear-negative cases. Steroids have no role in routine pulmonary tuberculosis and could worsen infection.', 'Medium', 61, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 41-year-old woman with pulmonary tuberculosis has been on RIPE therapy for 2 months, but her sputum cultures remain positive and she has had no clinical improvement. Drug susceptibility testing shows resistance to both isoniazid and rifampin. What is the most appropriate next step?', '["Continue RIPE therapy for the full 6 months", "Add streptomycin to the current regimen", "Switch to isoniazid and rifampin at higher doses", "Refer for a multidrug-resistant tuberculosis regimen with second-line drugs under specialist guidance", "Stop all antituberculous therapy and observe"]'::jsonb, 3, 'Resistance to both isoniazid and rifampin defines multidrug-resistant tuberculosis, which cannot be cured with first-line drugs; continuing RIPE risks treatment failure and further resistance. Management requires a second-line regimen (for example bedaquiline, a fluoroquinolone, linezolid, and clofazimine) tailored to susceptibility testing and given under expert supervision, often for 18 to 24 months. Adding a single drug to a failing regimen only breeds more resistance. Higher doses of the same drugs do not overcome resistance. Stopping therapy allows progressive disease and ongoing transmission.', 'Hard', 62, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 28-year-old man with HIV and a CD4 count of 35 cells per microliter presents with 3 weeks of cough, fever, and weight loss. Chest X-ray shows diffuse infiltrates without cavitation. Sputum smears are negative for acid-fast bacilli, but nucleic acid amplification testing is positive for Mycobacterium tuberculosis. What is the most appropriate management?', '["Start RIPE therapy and begin antiretroviral therapy within 2 weeks of starting tuberculosis treatment", "Delay antiretroviral therapy until tuberculosis treatment is complete", "Start RIPE therapy only and defer antiretroviral therapy indefinitely", "Treat with isoniazid monotherapy", "Repeat sputum smears and withhold treatment until culture confirms tuberculosis"]'::jsonb, 0, 'Nucleic acid amplification testing confirms active tuberculosis despite negative smears, which are common in HIV because of lower bacillary burden and atypical radiographs. RIPE therapy is started immediately, and antiretroviral therapy is begun within 2 weeks because the CD4 count is below 50 cells per microliter, which reduces mortality despite the risk of immune reconstitution inflammatory syndrome. Delaying antiretroviral therapy until tuberculosis treatment ends leaves the patient profoundly immunosuppressed. Isoniazid alone is inadequate for active disease. Waiting for culture delays treatment by weeks and risks progression.', 'Hard', 63, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 52-year-old woman presents with 3 weeks of headache, low-grade fever, confusion, and neck stiffness. Lumbar puncture shows lymphocytic pleocytosis, elevated protein, low glucose, and elevated opening pressure. What is the most likely diagnosis and the most appropriate next step?', '["Bacterial meningitis — start ceftriaxone and vancomycin", "Viral meningitis — supportive care only", "Cryptococcal meningitis — start amphotericin B and flucytosine", "Subarachnoid hemorrhage — obtain CT angiography", "Tuberculous meningitis — start RIPE therapy plus adjunctive corticosteroids"]'::jsonb, 4, 'Subacute meningitis over weeks with lymphocytic pleocytosis, high protein, and low cerebrospinal fluid glucose is classic for tuberculous meningitis, which carries high mortality if treatment is delayed, so empiric RIPE therapy plus adjunctive dexamethasone is started while cultures and nucleic acid amplification testing are pending. Bacterial meningitis is typically acute with neutrophilic cerebrospinal fluid and high fever. Viral meningitis usually has normal glucose and a benign course. Cryptococcal meningitis occurs mainly in advanced HIV and is diagnosed by cerebrospinal fluid antigen testing. Subarachnoid hemorrhage causes sudden severe headache, not weeks of fever and confusion.', 'Medium', 64, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 67-year-old man presents with 6 weeks of fever, weight loss, and dyspnea. Chest X-ray shows diffuse 1 to 2 mm nodules throughout both lungs. Sputum smears are negative for acid-fast bacilli. What is the most likely diagnosis?', '["Pneumocystis pneumonia", "Metastatic lung cancer", "Miliary tuberculosis", "Sarcoidosis", "Hypersensitivity pneumonitis"]'::jsonb, 2, 'Diffuse miliary (millet-seed) nodules on chest imaging with prolonged fever and weight loss are characteristic of hematogenously disseminated miliary tuberculosis; sputum smears are often negative because bacilli are scattered in tissue rather than airways, and diagnosis may require biopsy or culture of blood, bone marrow, or liver. Pneumocystis causes ground-glass opacities in immunocompromised hosts, not discrete miliary nodules. Metastatic cancer produces larger, variably sized nodules and usually a known primary tumor. Sarcoidosis favors hilar adenopathy with perilymphatic nodules. Hypersensitivity pneumonitis causes ground-glass change and centrilobular nodules after antigen exposure, not a chronic febrile wasting illness.', 'Medium', 65, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 24-year-old woman presents with painless, enlarging cervical lymph nodes for 2 months, low-grade fever, and night sweats. The nodes are firm, matted, and non-tender. Chest X-ray is normal. What is the most appropriate next diagnostic step?', '["Start broad-spectrum antibiotics for bacterial lymphadenitis", "Excisional or fine-needle aspiration biopsy of the node for AFB smear, culture, and histology", "Order neck ultrasound and observe for 3 months", "Start RIPE therapy without tissue diagnosis", "Perform HIV testing only and defer further workup"]'::jsonb, 1, 'Painless matted cervical adenopathy with systemic symptoms suggests tuberculous lymphadenitis (scrofula), the most common form of extrapulmonary tuberculosis; tissue diagnosis is essential, with fine-needle aspiration or excisional biopsy sent for AFB smear, mycobacterial culture, and histology showing caseating granulomas. Bacterial lymphadenitis is usually tender, erythematous, and acute. Ultrasound and observation delay diagnosis of a treatable infection. Starting RIPE therapy without confirmation risks treating the wrong disease, such as lymphoma. HIV testing is appropriate but is not a substitute for tissue diagnosis.', 'Medium', 66, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 30-year-old healthcare worker has a positive interferon-gamma release assay, a normal chest X-ray, and no symptoms. She has never been treated for tuberculosis. What is the most appropriate management?', '["No treatment; repeat testing in 1 year", "Start four-drug RIPE therapy for 6 months", "Order sputum cultures and isolate the patient", "Treat latent tuberculosis infection with isoniazid daily for 9 months or rifampin daily for 4 months", "Start isoniazid and rifampin for 2 months only"]'::jsonb, 3, 'A positive interferon-gamma release assay with a normal chest radiograph and no symptoms indicates latent tuberculosis infection, not active disease, so the patient is not infectious and needs no isolation or sputum cultures. Treatment of latent infection prevents progression to active tuberculosis; standard regimens include isoniazid daily for 9 months or rifampin daily for 4 months, with the choice based on drug interactions and adherence. No treatment leaves a 5 to 10 percent lifetime risk of reactivation. Four-drug RIPE therapy is treatment for active tuberculosis and is unnecessary. Two months of two drugs is not an accepted latent tuberculosis regimen.', 'Easy', 67, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 45-year-old man is a household contact of a patient with smear-positive pulmonary tuberculosis. He is asymptomatic with a normal chest X-ray, but his tuberculin skin test is positive at 14 mm of induration. He has diabetes mellitus. What is the most appropriate next step?', '["Treat latent tuberculosis infection, prioritizing him because diabetes increases reactivation risk", "Reassure him; a positive skin test in a contact needs no treatment", "Start RIPE therapy for active tuberculosis", "Repeat the skin test in 6 months before deciding", "Order sputum AFB smears to rule out active disease"]'::jsonb, 0, 'A 14 mm tuberculin reaction in a close contact of infectious tuberculosis indicates latent infection, and diabetes mellitus substantially increases the risk of progression to active disease, so treatment of latent tuberculosis is indicated. Reassurance ignores the well-documented reactivation risk in contacts with comorbidities. RIPE therapy is for active tuberculosis, which he does not have given the absence of symptoms and a normal radiograph. Repeating the skin test adds nothing once positivity is established. Sputum smears are unnecessary without respiratory symptoms or radiographic disease.', 'Medium', 68, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 58-year-old man in the intensive care unit with a central venous catheter, on broad-spectrum antibiotics and total parenteral nutrition, develops persistent fever despite antibiotics. Blood cultures grow Candida albicans. What is the most appropriate management?', '["Remove the catheter only; antifungal therapy is unnecessary", "Start fluconazole and continue the central line", "Start amphotericin B deoxycholate as first-line therapy", "Start oral nystatin", "Remove the central venous catheter and start an echinocandin such as micafungin"]'::jsonb, 4, 'Candidemia in a critically ill patient with a central line requires prompt source control by removing the catheter plus systemic antifungal therapy; echinocandins are first-line for candidemia in critically ill or azole-exposed patients because of their fungicidal activity and reliability against most Candida species. Removing the line alone does not clear bloodstream infection. Fluconazole is an alternative in stable, azole-naive patients but is less reliable in the critically ill. Amphotericin B deoxycholate is reserved for refractory cases because of nephrotoxicity. Oral nystatin is not absorbed and has no role in bloodstream infection.', 'Medium', 69, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 63-year-old woman treated for candidemia 1 week ago reports blurred vision and eye pain. Fundoscopy shows white retinal infiltrates. What is the most appropriate next step?', '["Reassure her; ocular symptoms are expected and self-limited", "Start topical antifungal eye drops only", "Urgent ophthalmology evaluation and systemic antifungal therapy, with vitrectomy considered for severe disease", "Stop antifungal therapy because the eye is involved", "Start oral corticosteroids for the eye inflammation"]'::jsonb, 2, 'Candida endophthalmitis is a sight-threatening complication of candidemia that requires urgent ophthalmologic evaluation and continued systemic antifungal therapy; severe vitritis may need intravitreal antifungals or vitrectomy. Reassurance risks permanent vision loss. Topical drops do not penetrate the vitreous. Stopping antifungals allows the infection to progress. Corticosteroids suppress immunity and worsen fungal infection. The eye is a sanctuary site where hematogenous seeding can smolder even after blood cultures clear, which is why every patient with candidemia needs a dilated fundoscopic examination. Intravitreal injection of amphotericin B or voriconazole may be added when vitritis is dense, and vitrectomy helps clear the infectious burden. Delaying evaluation risks retinal detachment and irreversible blindness.', 'Medium', 70, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 47-year-old man with acute myeloid leukemia and prolonged neutropenia after chemotherapy develops fever unresponsive to broad-spectrum antibiotics, pleuritic chest pain, and hemoptysis. CT of the chest shows a nodule with a halo sign. Serum galactomannan is positive. What is the most likely diagnosis and treatment?', '["Bacterial pneumonia — add vancomycin", "Pneumocystis pneumonia — start trimethoprim-sulfamethoxazole", "Pulmonary embolism — start heparin", "Invasive pulmonary aspergillosis — start voriconazole", "Tuberculosis — start RIPE therapy"]'::jsonb, 3, 'Prolonged neutropenia with fever refractory to antibiotics, hemoptysis, a halo-sign nodule, and positive galactomannan is classic for invasive pulmonary aspergillosis; voriconazole is first-line therapy. Bacterial pneumonia does not produce the halo sign or positive galactomannan. Pneumocystis causes diffuse ground-glass opacities, usually with hypoxemia and elevated lactate dehydrogenase. Pulmonary embolism does not explain prolonged neutropenic fever or galactomannan positivity. Tuberculosis is less likely in this acute neutropenic presentation and lacks the halo sign. The halo sign reflects hemorrhage around an infarcted nodule and is highly suggestive of angioinvasive fungal infection in neutropenia. Treatment should start promptly because mortality rises sharply with delay, and neutrophil recovery is the key determinant of outcome.', 'Medium', 71, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 26-year-old woman with cystic fibrosis has recurrent wheezing, mucus plugging, and worsening asthma control. Total IgE is markedly elevated, Aspergillus-specific IgE is positive, and sputum grows Aspergillus fumigatus. Chest imaging shows central bronchiectasis. What is the most likely diagnosis?', '["Invasive pulmonary aspergillosis", "Allergic bronchopulmonary aspergillosis", "Chronic pulmonary aspergillosis", "Aspergilloma", "Asthma exacerbation from viral infection"]'::jsonb, 1, 'Allergic bronchopulmonary aspergillosis occurs in asthma and cystic fibrosis, with markedly elevated total IgE, Aspergillus-specific IgE, central bronchiectasis, and mucus plugging — an allergic response to airway colonization rather than tissue invasion. Invasive aspergillosis occurs in profoundly immunocompromised hosts with tissue invasion and halo-sign nodules. Chronic pulmonary aspergillosis causes progressive cavitary disease over months. An aspergilloma is a fungus ball in a preexisting cavity. A viral exacerbation does not explain the markedly elevated IgE or Aspergillus-specific antibodies. Treatment centers on systemic corticosteroids to suppress the allergic inflammation, often with itraconazole to reduce fungal burden, and monitoring total IgE to follow response. Antifungal therapy alone does not control the immune-mediated airway damage.', 'Hard', 72, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 39-year-old man with HIV and a CD4 count of 45 cells per microliter presents with 2 weeks of headache, fever, and confusion. Cerebrospinal fluid opening pressure is elevated, with lymphocytic pleocytosis and low glucose. Cerebrospinal fluid cryptococcal antigen is positive. What is the most appropriate induction therapy?', '["Amphotericin B plus flucytosine for 2 weeks, then fluconazole", "Fluconazole alone for 2 weeks", "Amphotericin B alone for 6 weeks", "Voriconazole plus caspofungin", "No antifungal therapy; start antiretroviral therapy immediately"]'::jsonb, 0, 'Cryptococcal meningitis in advanced HIV is treated with induction amphotericin B plus flucytosine for at least 2 weeks, followed by fluconazole consolidation and maintenance, because combination therapy clears the organism faster and reduces mortality. Fluconazole alone is inadequate for induction in severe disease. Amphotericin B without flucytosine is less effective. Voriconazole and echinocandins are not first-line for cryptococcal meningitis. Starting antiretroviral therapy immediately without antifungal treatment risks immune reconstitution inflammatory syndrome and death. Serial lumbar punctures or a shunt may be needed to manage raised intracranial pressure, a major cause of death. Antiretroviral therapy is deferred for about 4 to 6 weeks to reduce the risk of immune reconstitution inflammatory syndrome.', 'Medium', 73, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 44-year-old man newly diagnosed with HIV has a CD4 count of 80 cells per microliter and is asymptomatic. Serum cryptococcal antigen is positive. What is the most appropriate management?', '["No treatment; repeat antigen testing in 6 months", "Start amphotericin B and flucytosine", "Begin antiretroviral therapy immediately and ignore the antigen", "Order lumbar puncture and withhold all treatment pending results", "Start preemptive fluconazole and perform lumbar puncture to exclude meningitis"]'::jsonb, 4, 'A positive serum cryptococcal antigen in a patient with advanced HIV indicates cryptococcal antigenemia, which precedes meningitis; preemptive fluconazole reduces progression, and lumbar puncture is performed to exclude subclinical meningitis, which would require full induction therapy. Ignoring the result risks fatal meningitis. Amphotericin B plus flucytosine is induction therapy for confirmed meningitis, not for asymptomatic antigenemia. Antiretroviral therapy alone does not treat cryptococcal infection. Withholding fluconazole while awaiting lumbar puncture delays preventive treatment. Cryptococcal antigenemia is a strong predictor of meningitis and death in advanced HIV, so screening is recommended when the CD4 count is below 100 cells per microliter. If lumbar puncture confirms meningitis, full induction therapy is required instead of preemptive fluconazole alone.', 'Hard', 74, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 55-year-old man from the Ohio River Valley with HIV and a CD4 count of 60 cells per microliter presents with fever, weight loss, hepatosplenomegaly, and pancytopenia. Urine Histoplasma antigen is positive. What is the most likely diagnosis and treatment?', '["Disseminated tuberculosis — start RIPE therapy", "Lymphoma — refer for chemotherapy", "Disseminated histoplasmosis — start liposomal amphotericin B, then itraconazole", "Cytomegalovirus disease — start ganciclovir", "Bacterial sepsis — continue broad-spectrum antibiotics"]'::jsonb, 2, 'Disseminated histoplasmosis is common in the Ohio River Valley in advanced HIV, presenting with fever, wasting, hepatosplenomegaly, and pancytopenia; urine antigen testing is sensitive for disseminated disease. Severe disseminated disease is treated with liposomal amphotericin B induction followed by itraconazole maintenance. Tuberculosis can mimic this picture but urine Histoplasma antigen is specific. Lymphoma causes similar symptoms but the positive antigen test points to histoplasmosis. Cytomegalovirus typically causes retinitis or colitis. Bacterial sepsis does not explain the chronic wasting course with a positive fungal antigen.', 'Medium', 75, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 31-year-old man from Arizona develops fever, cough, chest pain, and erythema nodosum 2 weeks after a dust storm. Chest X-ray shows a right lower lobe infiltrate. Sputum cultures are negative for bacteria. What is the most likely diagnosis?', '["Acute pulmonary coccidioidomycosis (Valley fever)", "Community-acquired bacterial pneumonia", "Pulmonary tuberculosis", "Histoplasmosis", "Sarcoidosis"]'::jsonb, 0, 'Acute pulmonary coccidioidomycosis follows inhalation of Coccidioides spores in the desert Southwest, often after dust exposure, and presents with pneumonia-like illness plus erythema nodosum, a marker of a good immune response. Bacterial pneumonia lacks the exposure history and erythema nodosum. Tuberculosis is more chronic with cavitary upper-lobe disease. Histoplasmosis is associated with the Ohio-Mississippi River valleys and bird or bat droppings. Sarcoidosis causes hilar adenopathy and is not linked to acute dust exposure with pneumonia. Most cases are self-limited and need only supportive care, but disseminated disease in immunocompromised hosts requires antifungal therapy with fluconazole or amphotericin B. Complement fixation titers help follow the course of disease.', 'Medium', 76, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 48-year-old man from Wisconsin presents with chronic cough, hemoptysis, and verrucous skin lesions on the face. Sputum microscopy shows broad-based budding yeast. What is the most likely diagnosis and treatment?', '["Tuberculosis — start RIPE therapy", "Squamous cell carcinoma — refer for excision", "Bacterial pneumonia — start levofloxacin", "Blastomycosis — start itraconazole (amphotericin B if severe)", "Cryptococcosis — start fluconazole"]'::jsonb, 3, 'Blastomycosis, endemic to the Great Lakes and Mississippi River regions, causes chronic pulmonary disease plus verrucous skin lesions, and broad-based budding yeast on microscopy is diagnostic. Mild-to-moderate disease is treated with itraconazole, while severe or central nervous system disease requires amphotericin B. Tuberculosis does not cause verrucous skin lesions or broad-based budding yeast. Squamous cell carcinoma does not explain the pulmonary syndrome or yeast forms. Bacterial pneumonia lacks skin lesions and yeast. Cryptococcus shows narrow-based budding yeast, not broad-based forms.', 'Hard', 77, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 29-year-old traveler returning from sub-Saharan Africa presents with cyclic high fevers, chills, headache, thrombocytopenia, and anemia. Blood smear shows Plasmodium falciparum with 4 percent parasitemia. He is alert with normal blood pressure. What is the most appropriate treatment?', '["Chloroquine alone", "Artemether-lumefantrine (artemisinin-based combination therapy)", "Primaquine alone", "Doxycycline alone", "Supportive care only; malaria resolves spontaneously"]'::jsonb, 1, 'Uncomplicated falciparum malaria is treated with artemisinin-based combination therapy such as artemether-lumefantrine, which rapidly clears parasites and reduces resistance. Chloroquine is ineffective against falciparum in most of Africa because of widespread resistance. Primaquine targets liver hypnozoites in vivax and ovale malaria and is not treatment for acute falciparum infection. Doxycycline alone acts too slowly for acute treatment. Untreated falciparum malaria can progress to severe disease and death, so supportive care alone is unsafe. Patients should be monitored for complications such as hemolysis, hypoglycemia, and acute kidney injury, and repeat smears confirm parasite clearance. Severe disease with impaired consciousness, severe anemia, or organ dysfunction requires intravenous artesunate instead.', 'Medium', 78, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 6-year-old child in Nigeria presents with fever, impaired consciousness, severe anemia with hemoglobin 4.5 g/dL, and jaundice. Blood smear is positive for Plasmodium falciparum. What is the most appropriate management?', '["Oral artemether-lumefantrine and discharge home", "Chloroquine and observation", "Blood transfusion only", "Quinine infusion as first-line therapy", "Intravenous artesunate plus supportive care including transfusion as needed"]'::jsonb, 4, 'Severe falciparum malaria with cerebral involvement and severe anemia is a medical emergency; intravenous artesunate is first-line because it reduces mortality compared with quinine, and supportive care including blood transfusion for severe anemia is essential. Oral therapy is inadequate in a child with impaired consciousness who cannot reliably swallow. Chloroquine is ineffective against resistant falciparum. Transfusion alone does not kill parasites. Quinine is an alternative only when artesunate is unavailable and carries higher mortality and more adverse effects. Blood transfusion is given for hemoglobin below 5 g per deciliter or with signs of respiratory distress, and hypoglycemia and seizures must be watched for. Early treatment dramatically improves survival in children.', 'Medium', 79, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 35-year-old woman traveling to rural Kenya for 3 weeks asks about malaria prevention. She has no contraindications to any prophylactic drug. What is the most appropriate recommendation?', '["No prophylaxis is needed; treat only if symptoms develop", "Insect repellent alone is sufficient", "Atovaquone-proguanil chemoprophylaxis plus insect bite precautions", "Chloroquine weekly is the best choice", "A single dose of artemether-lumefantrine before travel"]'::jsonb, 2, 'Travelers to high-transmission areas need chemoprophylaxis plus bite precautions; atovaquone-proguanil is effective against chloroquine-resistant falciparum and is well tolerated. No prophylaxis leaves the traveler at risk of severe disease. Repellent alone is insufficient. Chloroquine is ineffective in East Africa because of resistance. Artemether-lumefantrine is a treatment regimen, not prophylaxis, and a single pre-travel dose offers no protection. Prophylaxis should start before travel, continue throughout the stay, and be taken for 7 days after leaving the area for atovaquone-proguanil. Insecticide-treated bed nets, long sleeves, and DEET repellent add further protection, especially at night when Anopheles mosquitoes bite.', 'Easy', 80, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 42-year-old man with HIV, a CD4 count of 60 cells per microliter, and no antiretroviral therapy presents with headache, confusion, and right-sided weakness. MRI shows multiple ring-enhancing lesions in the basal ganglia. Toxoplasma IgG is positive. What is the most likely diagnosis and treatment?', '["Primary central nervous system lymphoma — start chemotherapy", "Cerebral toxoplasmosis — start pyrimethamine plus sulfadiazine", "Bacterial brain abscess — start ceftriaxone and metronidazole", "Tuberculoma — start RIPE therapy", "Progressive multifocal leukoencephalopathy — start antiretroviral therapy only"]'::jsonb, 1, 'In advanced HIV, multiple ring-enhancing lesions in the basal ganglia with positive Toxoplasma IgG strongly suggest cerebral toxoplasmosis, treated with pyrimethamine plus sulfadiazine (with leucovorin). Primary central nervous system lymphoma usually causes a single lesion and is Epstein-Barr virus driven. Bacterial abscesses are less common in this setting and lack the characteristic basal ganglia distribution. Tuberculomas are possible but less likely with positive Toxoplasma serology. Progressive multifocal leukoencephalopathy causes non-enhancing white matter lesions without mass effect. Treatment is usually continued for at least 6 weeks, followed by maintenance therapy until immune recovery on antiretroviral therapy. Clinical and radiologic improvement within 2 weeks supports the diagnosis, and lack of response should prompt brain biopsy.', 'Medium', 81, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 27-year-old pregnant woman at 16 weeks gestation has positive Toxoplasma IgM and IgG with low IgG avidity, suggesting acute infection. Ultrasound is normal. What is the most appropriate management?', '["Terminate the pregnancy", "Start pyrimethamine plus sulfadiazine immediately", "Reassure her; no treatment is needed in pregnancy", "Start spiramycin to reduce fetal transmission and refer for amniocentesis", "Start trimethoprim-sulfamethoxazole"]'::jsonb, 3, 'Acute toxoplasmosis in early pregnancy risks congenital infection, and spiramycin concentrates in the placenta to reduce fetal transmission; amniocentesis with polymerase chain reaction testing after 18 weeks determines whether the fetus is infected. Termination is not indicated without evidence of fetal infection. Pyrimethamine plus sulfadiazine is teratogenic in the first trimester and is reserved for confirmed fetal infection later in pregnancy. Reassurance ignores the risk of congenital toxoplasmosis, which can cause chorioretinitis and neurologic damage. Trimethoprim-sulfamethoxazole is not the recommended regimen for preventing fetal transmission.', 'Hard', 82, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 38-year-old man from Connecticut presents in July with an expanding annular rash with central clearing on his thigh, fever, and myalgias. He has no neurologic or cardiac symptoms. What is the most likely diagnosis and treatment?', '["Early localized Lyme disease — doxycycline for 10 days", "Cellulitis — cephalexin for 7 days", "Erythema multiforme — supportive care", "Rocky Mountain spotted fever — doxycycline for 14 days", "Early localized Lyme disease — single dose of ceftriaxone"]'::jsonb, 0, 'Erythema migrans — an expanding annular rash with central clearing — is diagnostic of early localized Lyme disease, and doxycycline for 10 days is first-line treatment in adults. Cellulitis is warm, tender, and lacks central clearing. Erythema multiforme causes target lesions, often on palms and soles, after herpes infection or drugs. Rocky Mountain spotted fever causes a petechial rash starting on wrists and ankles. Ceftriaxone is reserved for disseminated or neurologic Lyme disease, not early localized disease. A single 200 mg dose of doxycycline can prevent Lyme disease after a high-risk tick bite, but it is not treatment for established erythema migrans. Patients should be examined for other tick-borne infections such as anaplasmosis and babesiosis.', 'Easy', 83, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 45-year-old woman treated for Lyme disease 6 weeks ago with 10 days of doxycycline now presents with facial nerve palsy and intermittent knee swelling. What is the most appropriate next step?', '["Reassure her; these are expected post-treatment symptoms", "Start oral amoxicillin for 14 days", "Start prednisone for the facial palsy", "Order Lyme serology to confirm reinfection", "Treat with intravenous ceftriaxone for disseminated Lyme disease with cranial nerve involvement"]'::jsonb, 4, 'Facial nerve palsy after Lyme disease indicates early disseminated infection with neurologic involvement, which requires intravenous ceftriaxone; oral doxycycline is adequate for early localized disease but not for cranial nerve palsy. Reassurance misses an active infection that can progress. Oral amoxicillin is used for early localized disease, not neurologic dissemination. Prednisone alone does not treat the underlying Borrelia infection. Serology is often already positive and does not guide acute management. Lyme arthritis typically affects the knee and may need a longer course of oral doxycycline or ceftriaxone if it persists. Post-treatment Lyme disease syndrome with fatigue and arthralgia is managed supportively, not with prolonged antibiotics.', 'Hard', 84, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 60-year-old man from Southeast Asia on high-dose corticosteroids for chronic obstructive pulmonary disease develops severe diarrhea, gram-negative bacteremia, and respiratory failure. Stool examination shows Strongyloides larvae. What is the most likely diagnosis and treatment?', '["Bacterial sepsis — continue antibiotics only", "Hookworm infection — start albendazole", "Strongyloides hyperinfection syndrome — start ivermectin", "Amebic colitis — start metronidazole", "Clostridioides difficile colitis — start vancomycin"]'::jsonb, 2, 'Strongyloides hyperinfection occurs when immunosuppression, especially corticosteroids, triggers massive larval dissemination, causing gram-negative bacteremia from translocated gut bacteria and respiratory failure; ivermectin is the treatment of choice. Antibiotics alone do not kill the parasite. Hookworm causes iron-deficiency anemia, not hyperinfection with bacteremia. Amebic colitis presents with bloody dysentery, not larval dissemination. Clostridioides difficile causes watery diarrhea after antibiotics but does not explain Strongyloides larvae or gram-negative bacteremia. Hyperinfection can also cause meningitis and gram-negative sepsis, so broad-spectrum antibiotics are given alongside ivermectin. All patients starting corticosteroids who have lived in endemic areas should be screened for Strongyloides first.', 'Hard', 85, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'An 8-year-old boy from rural Guatemala presents with cough, wheezing, and eosinophilia. Chest X-ray shows transient pulmonary infiltrates. A few weeks later he passes a large worm in his stool. What is the most likely diagnosis?', '["Ascariasis with Löffler syndrome", "Bacterial pneumonia", "Asthma", "Hookworm infection", "Schistosomiasis"]'::jsonb, 0, 'Ascaris lumbricoides larvae migrate through the lungs, causing cough, wheeze, eosinophilia, and transient infiltrates (Löffler syndrome), followed weeks later by adult worms in the stool. Bacterial pneumonia does not cause eosinophilia or passage of worms. Asthma does not explain the worm in the stool. Hookworm larvae also migrate through lungs but the classic presentation is iron-deficiency anemia and the adult worms are not passed visibly. Schistosomiasis causes Katayama fever and later portal hypertension or hematuria, not Löffler syndrome with a passed worm.', 'Medium', 86, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 22-year-old man who swam in Lake Malawi 3 months ago presents with fever, urticaria, eosinophilia, and painless terminal hematuria. Urine microscopy shows eggs with a terminal spine. What is the most likely diagnosis and treatment?', '["Urinary tract infection — start nitrofurantoin", "Bladder cancer — refer for cystoscopy", "Schistosoma mansoni infection — start praziquantel", "Schistosoma haematobium infection — start praziquantel", "Glomerulonephritis — start corticosteroids"]'::jsonb, 3, 'Schistosoma haematobium causes urinary schistosomiasis with terminal hematuria, and its eggs have a characteristic terminal spine; acute Katayama syndrome explains the fever, urticaria, and eosinophilia after freshwater exposure. Praziquantel is the treatment of choice. A urinary tract infection does not cause eosinophilia or eggs in urine. Bladder cancer is unlikely at age 22 and does not explain the systemic syndrome. Schistosoma mansoni eggs have a lateral spine and cause intestinal and hepatic disease. Glomerulonephritis does not produce terminal-spined eggs. Chronic infection can lead to bladder fibrosis, obstructive uropathy, and squamous cell carcinoma of the bladder. Treatment kills adult worms but does not reverse established fibrosis, so early diagnosis matters.', 'Medium', 87, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 50-year-old woman on RIPE therapy for pulmonary tuberculosis for 3 weeks develops nausea, vomiting, jaundice, and right upper quadrant pain. AST is 850 U/L, ALT is 920 U/L, and bilirubin is 5.2 mg/dL. What is the most appropriate management?', '["Continue RIPE therapy; liver enzyme elevation is expected and harmless", "Stop all hepatotoxic antituberculous drugs and reintroduce them one at a time after liver function normalizes", "Add prednisone to protect the liver", "Switch to isoniazid monotherapy", "Stop pyrazinamide only and continue the rest"]'::jsonb, 1, 'Drug-induced hepatitis from isoniazid, rifampin, and pyrazinamide requires stopping all potentially hepatotoxic agents until liver enzymes normalize, then reintroducing them sequentially to identify the culprit while maintaining effective therapy. Continuing treatment risks fulminant hepatic failure. Prednisone does not treat drug-induced hepatitis. Isoniazid monotherapy is itself hepatotoxic and inadequate for active tuberculosis. Stopping only pyrazinamide is insufficient because isoniazid and rifampin are also hepatotoxic. A non-hepatotoxic bridging regimen with ethambutol, a fluoroquinolone, and an injectable agent may be used while the liver recovers. Baseline liver function tests should be checked before starting therapy, especially in patients with liver disease or alcohol use.', 'Medium', 88, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 55-year-old woman with advanced HIV and a CD4 count of 90 cells per microliter presents with painful swallowing and retrosternal burning. Endoscopy shows white plaques in the esophagus. What is the most likely diagnosis and treatment?', '["Gastroesophageal reflux — start a proton pump inhibitor", "Herpes esophagitis — start acyclovir", "Cytomegalovirus esophagitis — start ganciclovir", "Candida esophagitis — start oral nystatin", "Candida esophagitis — start systemic fluconazole"]'::jsonb, 4, 'Candida esophagitis in advanced HIV presents with odynophagia and white plaques on endoscopy; systemic fluconazole is first-line therapy. Reflux does not cause white plaques. Herpes esophagitis causes small discrete ulcers, and cytomegalovirus causes large deep ulcers. Oral nystatin is not absorbed and does not treat esophageal candidiasis. Endoscopy is the gold standard for diagnosis, showing white plaques that do not wash off, and biopsy confirms pseudohyphae invading tissue. Most patients improve within days of fluconazole, and antiretroviral therapy reduces recurrence. Refractory cases may need echinocandins or amphotericin B.', 'Easy', 89, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 62-year-old man with prior tuberculosis and a residual lung cavity develops chronic cough, hemoptysis, and weight loss over 6 months. CT shows a fungus ball within the cavity with an air crescent sign. What is the most likely diagnosis and treatment?', '["Recurrent tuberculosis — restart RIPE therapy", "Lung cancer — refer for biopsy", "Aspergilloma — surgical resection if symptomatic, otherwise antifungal therapy and monitoring", "Bacterial lung abscess — start prolonged antibiotics", "Invasive aspergillosis — start voriconazole immediately"]'::jsonb, 2, 'An aspergilloma is a fungus ball growing in a preexisting cavity, typically after tuberculosis, and appears as a mobile mass with an air crescent sign; symptomatic patients with hemoptysis often need surgical resection, while antifungals have a limited role. Recurrent tuberculosis does not produce a fungus ball with an air crescent. Lung cancer would appear as a solid mass rather than a mobile intracavitary ball. A bacterial abscess has an air-fluid level and acute features. Invasive aspergillosis occurs in neutropenic hosts with tissue invasion, not as a fungus ball in a stable cavity.', 'Medium', 90, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 24-year-old man presents with 3 days of dysuria and purulent urethral discharge. He reports unprotected sexual intercourse with a new partner 1 week ago. Gram stain of the discharge shows gram-negative intracellular diplococci. Nucleic acid amplification testing is positive for Neisseria gonorrhoeae and negative for Chlamydia trachomatis. He has no drug allergies. Which of the following is the most appropriate treatment?', '["Ceftriaxone 500 mg intramuscularly as a single dose", "Azithromycin 1 g orally as a single dose", "Doxycycline 100 mg orally twice daily for 7 days", "Ciprofloxacin 500 mg orally as a single dose", "Penicillin G benzathine 2.4 million units intramuscularly as a single dose"]'::jsonb, 0, 'Uncomplicated gonococcal urethritis is treated with a single 500 mg intramuscular dose of ceftriaxone, which is the CDC-recommended regimen because of rising resistance to older agents. Azithromycin alone is no longer adequate monotherapy due to widespread macrolide resistance and is not recommended for gonorrhea. Doxycycline is the treatment for chlamydia, not gonorrhea, and would leave the gonococcal infection untreated. Ciprofloxacin is no longer recommended because fluoroquinolone-resistant N. gonorrhoeae is now common in the United States. Benzathine penicillin G treats syphilis, not gonorrhea, and gonococcal penicillin resistance is widespread.', 'Medium', 91, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 68-year-old woman with a history of chronic kidney disease is admitted with hospital-acquired pneumonia. Sputum culture grows Pseudomonas aeruginosa susceptible to piperacillin-tazobactam. She is started on intravenous piperacillin-tazobactam. On day 5 she develops profuse watery diarrhea, abdominal cramping, and fever. Stool testing is positive for Clostridioides difficile toxin. Which of the following best explains the mechanism by which her antibiotic contributed to this infection?', '["Suppression of normal colonic flora allowing C. difficile overgrowth and toxin production", "Direct stimulation of C. difficile spore germination by beta-lactam antibiotics", "Inhibition of colonic mucosal immunity by piperacillin-tazobactam", "Increased intestinal absorption of C. difficile toxin caused by tazobactam", "Allergic colitis triggered by the penicillin component of the regimen"]'::jsonb, 0, 'Broad-spectrum antibiotics such as piperacillin-tazobactam disrupt the normal colonic microbiota, removing colonization resistance and allowing C. difficile to proliferate and produce toxins A and B, which cause pseudomembranous colitis. Beta-lactams do not directly stimulate spore germination; germination is triggered by bile acids in the gut. Piperacillin-tazobactam does not inhibit mucosal immunity in a way that causes C. difficile infection. Tazobactam does not increase toxin absorption; the disease is mediated by toxin binding to colonic epithelium after overgrowth. This is not an allergic colitis, which would present with eosinophilia and a different clinical picture rather than toxin-positive watery diarrhea.', 'Medium', 92, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 55-year-old man with methicillin-resistant Staphylococcus aureus (MRSA) bacteremia is treated with intravenous vancomycin. After 1 week of therapy, his serum creatinine rises from 0.9 to 2.1 mg/dL, and trough vancomycin levels are supratherapeutic. Urinalysis shows muddy brown casts. Which of the following is the most likely mechanism of his acute kidney injury?', '["Acute tubular necrosis from vancomycin-induced tubular toxicity", "Acute interstitial nephritis from a hypersensitivity reaction to vancomycin", "Prerenal azotemia from volume depletion due to vancomycin-induced vomiting", "Cholesterol embolization from prolonged intravenous catheter use", "Obstructive uropathy from vancomycin crystalluria"]'::jsonb, 0, 'Vancomycin causes acute tubular necrosis through direct tubular toxicity, particularly at supratherapeutic levels, and muddy brown casts are the classic urinalysis finding of ATN. Acute interstitial nephritis typically presents with fever, rash, eosinophilia, and white blood cell casts rather than muddy brown casts, and is less characteristic of vancomycin. Prerenal azotemia shows a bland urinalysis with hyaline casts and a high BUN-to-creatinine ratio, not muddy brown casts. Cholesterol embolization causes livedo reticularis, eosinophilia, and eosinophiluria after arterial procedures, not muddy brown casts. Vancomycin does not commonly cause crystalluria or obstructive uropathy; that is more typical of drugs like acyclovir or sulfonamides.', 'Hard', 93, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 32-year-old pregnant woman at 12 weeks'' gestation presents with dysuria and frequency. Urinalysis shows leukocyte esterase and nitrites, and urine culture grows Escherichia coli susceptible to nitrofurantoin, trimethoprim-sulfamethoxazole, and ciprofloxacin. She has no fever or flank pain. Which of the following is the most appropriate treatment?', '["Nitrofurantoin 100 mg orally twice daily for 5 days", "Trimethoprim-sulfamethoxazole twice daily for 3 days", "Ciprofloxacin 500 mg orally twice daily for 3 days", "Amoxicillin-clavulanate for 14 days", "Observation without antibiotics since she is afebrile"]'::jsonb, 0, 'Nitrofurantoin is the preferred treatment for uncomplicated cystitis in pregnancy because it is effective against E. coli and has a favorable fetal safety profile in the first trimester when used for short courses, though it is avoided near term due to hemolytic anemia risk in the newborn. Trimethoprim-sulfamethoxazole is avoided in the first trimester because trimethoprim is a folate antagonist associated with neural tube defects, and sulfonamides near term risk kernicterus. Ciprofloxacin is contraindicated in pregnancy due to concerns about fetal cartilage toxicity. Amoxicillin-clavulanate is an alternative but 14 days is unnecessarily long for uncomplicated cystitis and it has higher failure rates. Observation is inappropriate because untreated bacteriuria in pregnancy can progress to pyelonephritis and is associated with preterm birth.', 'Medium', 94, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 45-year-old man with HIV and a CD4 count of 60 cells/mm3 is admitted with fever, headache, and confusion. Cerebrospinal fluid analysis shows elevated opening pressure, low glucose, and high protein. India ink stain reveals encapsulated yeast. Blood cultures grow Cryptococcus neoformans. Which of the following is the most appropriate initial antifungal therapy?', '["Amphotericin B plus flucytosine for induction therapy", "Fluconazole monotherapy at a high dose", "Voriconazole monotherapy", "Caspofungin monotherapy", "Itraconazole monotherapy"]'::jsonb, 0, 'Cryptococcal meningitis in advanced HIV requires induction therapy with amphotericin B plus flucytosine for at least 2 weeks, which provides the fastest fungicidal activity and reduces mortality compared with amphotericin B alone. Fluconazole monotherapy is fungistatic and too slow for induction in severe meningitis; it is used for consolidation and maintenance after induction. Voriconazole has activity against Cryptococcus but is not the recommended first-line induction agent and has more drug interactions. Caspofungin and other echinocandins have poor activity against Cryptococcus because the organism''s cell wall has little beta-glucan target, so they are ineffective. Itraconazole has poor central nervous system penetration and is not used for cryptococcal meningitis.', 'Hard', 95, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 62-year-old woman with acute myeloid leukemia develops persistent fever despite broad-spectrum antibiotics on day 12 of neutropenia. Chest CT shows a nodule with a surrounding halo of ground-glass opacity. Serum galactomannan is positive. Bronchoalveolar lavage grows Aspergillus fumigatus. Which of the following is the most appropriate first-line antifungal therapy?', '["Voriconazole", "Fluconazole", "Amphotericin B deoxycholate", "Caspofungin", "Nystatin"]'::jsonb, 0, 'Voriconazole is the first-line treatment for invasive pulmonary aspergillosis, with superior survival compared with amphotericin B deoxycholate in the landmark trial, and it is the drug of choice for the halo sign in a neutropenic patient. Fluconazole has no reliable activity against Aspergillus and is used mainly for Candida infections. Amphotericin B deoxycholate is effective but is second-line because of greater nephrotoxicity and infusion reactions, and liposomal formulations are preferred when amphotericin is used. Caspofungin is used as salvage therapy for aspergillosis, not first-line, because response rates are lower. Nystatin is a topical agent for mucocutaneous candidiasis and has no role in invasive pulmonary disease.', 'Medium', 96, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 58-year-old man with diabetes is admitted to the intensive care unit with septic shock and candidemia. Blood cultures grow Candida albicans. He is started on fluconazole. After 5 days he remains febrile with persistently positive blood cultures. His central venous catheter has been removed and repeat cultures remain positive. Which of the following is the most appropriate change in antifungal therapy?', '["Increase the fluconazole dose and continue monotherapy", "Switch to an echinocandin such as micafungin", "Add amphotericin B deoxycholate to fluconazole", "Switch to oral itraconazole", "Stop antifungal therapy and repeat blood cultures only"]'::jsonb, 1, 'Echinocandins such as micafungin are the first-line agents for candidemia in critically ill patients because they are fungicidal against Candida, have a favorable safety profile, and are recommended by IDSA guidelines over fluconazole in severe disease. Increasing fluconazole is unlikely to clear persistent candidemia and risks selecting for resistant species such as Candida glabrata. Adding amphotericin B deoxycholate increases nephrotoxicity without proven benefit over an echinocandin and is reserved for special situations. Itraconazole has erratic absorption, poor activity in candidemia, and is not recommended for bloodstream infection. Stopping therapy while blood cultures remain positive would allow uncontrolled disseminated candidiasis and is unsafe.', 'Hard', 97, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 28-year-old woman presents to the emergency department 36 hours after symptom onset with fever, myalgias, and cough during peak influenza season. Rapid influenza testing is positive for influenza A. She has no pneumonia, is not pregnant, and has no chronic medical conditions. Which of the following is the most appropriate management?', '["Amantadine 100 mg orally twice daily for 5 days", "Oseltamivir 75 mg orally twice daily for 5 days", "Acyclovir 800 mg orally five times daily for 7 days", "Ribavirin by inhalation for 3 days", "Supportive care only since she is otherwise healthy"]'::jsonb, 1, 'Oseltamivir is a neuraminidase inhibitor effective against influenza A and B, and it shortens symptom duration when started within 48 hours of onset, so it is the appropriate treatment here. Amantadine is no longer recommended because nearly all circulating influenza A strains are resistant to adamantanes. Acyclovir treats herpesviruses such as HSV and VZV, not influenza, and has no activity against influenza virus. Ribavirin is used for respiratory syncytial virus in selected infants and for hepatitis C, not for uncomplicated influenza in adults. Supportive care alone is reasonable in mild cases, but antiviral therapy is recommended for symptomatic patients presenting within 48 hours because it reduces symptom duration and complications.', 'Medium', 98, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 35-year-old man with newly diagnosed HIV has a CD4 count of 180 cells/mm3 and a viral load of 120,000 copies/mL. He has no opportunistic infections. He is started on antiretroviral therapy with bictegravir, tenofovir alafenamide, and emtricitabine. Two weeks later he develops nausea, fatigue, and dark urine. Laboratory tests show ALT 850 U/L and total bilirubin 4.2 mg/dL. Hepatitis B surface antigen is positive. Which of the following best explains his acute hepatitis?', '["Tenofovir-induced direct hepatotoxicity", "Immune reconstitution inflammatory syndrome with hepatitis B flare", "Bictegravir-induced acute liver failure", "Emtricitabine-induced lactic acidosis with hepatic steatosis", "Acute hepatitis A superinfection"]'::jsonb, 1, 'This patient has chronic hepatitis B coinfection, and starting antiretroviral therapy can trigger immune reconstitution inflammatory syndrome, in which restored immune function attacks HBV-infected hepatocytes and causes an acute hepatitis flare with markedly elevated transaminases. Tenofovir is actually active against hepatitis B and is not a common cause of direct hepatotoxicity; stopping it can cause HBV flares instead. Bictegravir is an integrase inhibitor with a low risk of hepatotoxicity and is not the usual cause of severe acute hepatitis. Emtricitabine rarely causes lactic acidosis with hepatic steatosis, which presents with elevated lactate and a different clinical picture rather than isolated transaminitis. Acute hepatitis A would require IgM anti-HAV positivity and an exposure history, and does not explain the timing after antiretroviral initiation in a patient with known chronic HBV.', 'Hard', 99, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 40-year-old man with a history of genital herpes presents with painful vesicular lesions on the penis that appeared 2 days ago. He reports similar episodes twice in the past year. He is otherwise healthy and not immunocompromised. Which of the following is the most appropriate treatment for this episode?', '["Oseltamivir 75 mg orally twice daily for 5 days", "Valacyclovir 500 mg orally twice daily for 3 days", "Ganciclovir 5 mg/kg intravenously twice daily for 14 days", "Foscarnet 40 mg/kg intravenously every 8 hours", "Topical acyclovir ointment applied five times daily"]'::jsonb, 1, 'Valacyclovir is the preferred oral treatment for recurrent genital herpes because it has better bioavailability than acyclovir and a short 3-day course is effective for episodic treatment, reducing lesion duration and viral shedding. Oseltamivir treats influenza, not herpes simplex virus, and has no anti-HSV activity. Intravenous ganciclovir is used for cytomegalovirus infection, not HSV, and carries significant myelosuppression risk. Foscarnet is reserved for acyclovir-resistant HSV in immunocompromised patients and is nephrotoxic, so it is not first-line for uncomplicated recurrent disease. Topical acyclovir is less effective than oral therapy for genital herpes and is not recommended as primary treatment for recurrent episodes.', 'Easy', 100, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 67-year-old man with chronic obstructive pulmonary disease and diabetes presents for a routine visit in October. He received the influenza vaccine last year and the pneumococcal polysaccharide vaccine (PPSV23) at age 65. He has never received a pneumococcal conjugate vaccine, a recombinant zoster vaccine, or a tetanus booster in the past 15 years. Which of the following vaccines is most important to administer today?', '["Recombinant zoster vaccine (RZV), two-dose series", "Pneumococcal conjugate vaccine 20 (PCV20) now, since he has not had a conjugate vaccine", "Tetanus-diphtheria (Td) booster", "Influenza vaccine for the current season", "Measles-mumps-rubella (MMR) vaccine"]'::jsonb, 3, 'The influenza vaccine is the most important vaccine to give today because it is October, the start of influenza season, and this patient has COPD and diabetes, which place him at high risk of severe influenza and its complications. PCV20 is also indicated since he has only received PPSV23, but influenza vaccination is time-sensitive and should not be delayed during flu season. The Td booster is due since it has been more than 10 years, but it is less urgent than the seasonal influenza vaccine. The recombinant zoster vaccine is recommended for adults over 50, but it is a two-dose series that can be given at a subsequent visit. MMR is not indicated because adults born before 1957 are presumed immune and he has no specific indication.', 'Medium', 101, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 72-year-old woman with no prior pneumococcal vaccination presents for a wellness visit. She has a history of hypertension and osteoarthritis. She received the influenza vaccine last month and the recombinant zoster vaccine series last year. According to current adult immunization recommendations, which of the following pneumococcal vaccines should she receive?', '["PPSV23 now followed by PCV20 in one year", "PCV20 as a single dose", "PCV15 followed by PPSV23 in one year", "No pneumococcal vaccine is needed until age 75", "PPSV23 alone as a single dose"]'::jsonb, 1, 'Adults aged 65 years and older who have never received a pneumococcal conjugate vaccine should receive a single dose of PCV20, which provides broader serotype coverage than earlier regimens and simplifies the schedule. Giving PPSV23 first followed by PCV20 is an outdated approach that is no longer recommended for vaccine-naive older adults. PCV15 followed by PPSV23 is an alternative regimen, but PCV20 alone is simpler and preferred when available. Pneumococcal vaccination is recommended at age 65, not deferred to 75, because invasive pneumococcal disease risk rises sharply with age. PPSV23 alone is no longer the recommended approach for vaccine-naive adults because conjugate vaccines provide better immunogenicity and longer-lasting protection.', 'Medium', 102, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 29-year-old woman who is 8 weeks pregnant presents for her first prenatal visit. She has no documentation of prior varicella vaccination and reports she never had chickenpox. She works as a daycare teacher. Which of the following is the most appropriate recommendation regarding varicella vaccination?', '["Administer the varicella vaccine now because her occupational exposure is high", "Defer varicella vaccination until after delivery and vaccinate postpartum", "Administer varicella immune globulin now for passive protection", "Administer the MMR vaccine now since it also covers varicella", "No vaccination is needed because varicella is mild in adults"]'::jsonb, 1, 'The varicella vaccine is a live attenuated vaccine and is contraindicated during pregnancy because of the theoretical risk of congenital varicella syndrome, so it should be deferred until after delivery and given postpartum before hospital discharge. Giving the vaccine now would expose the fetus to a live vaccine unnecessarily when the risk can be avoided by waiting. Varicella immune globulin is reserved for pregnant women with a significant exposure to varicella, not for routine prophylaxis in the absence of exposure. The MMR vaccine is also a live vaccine, is contraindicated in pregnancy, and does not protect against varicella. Varicella in pregnancy can cause severe maternal pneumonia and congenital varicella syndrome, so it is not a trivial infection in this setting.', 'Medium', 103, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 55-year-old man with asplenia due to a prior splenectomy presents for a routine visit. He received the pneumococcal polysaccharide vaccine 3 years ago and the Haemophilus influenzae type b vaccine at the time of splenectomy. He has never received a meningococcal vaccine. Which of the following is the most appropriate meningococcal vaccination for this patient?', '["No meningococcal vaccine is needed because he is over 50", "MenB vaccine only, since serogroup B is most common in adults", "MenACWY vaccine now, with a booster dose in 5 years", "MenACWY vaccine as a single lifetime dose", "Meningococcal polysaccharide vaccine only"]'::jsonb, 2, 'Patients with asplenia are at markedly increased risk of invasive meningococcal disease and should receive the MenACWY conjugate vaccine, with a booster every 5 years for as long as the risk persists. MenB vaccine is also recommended for asplenic patients, but MenACWY is the primary vaccine covering serogroups A, C, W, and Y, and MenB alone would leave him unprotected against those serogroups. Age over 50 does not remove the indication because the risk comes from asplenia, not age. A single lifetime dose is insufficient because antibody levels wane and boosters are recommended every 5 years in high-risk patients. The older polysaccharide vaccine is less immunogenic and is not preferred over the conjugate vaccine.', 'Hard', 104, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 26-year-old veterinary student is bitten on the hand by a stray dog while volunteering at an animal shelter. The dog is captured and appears healthy but cannot be observed for 10 days because it escaped from quarantine. The student has never received rabies vaccination. The wound is cleaned thoroughly. Which of the following is the most appropriate post-exposure prophylaxis?', '["Human rabies immune globulin alone without vaccine", "Rabies vaccine alone without immune globulin since the dog appeared healthy", "Human rabies immune globulin infiltrated around the wound plus a 4-dose rabies vaccine series", "Observation only, since the dog appeared healthy at the time of the bite", "A single dose of rabies vaccine and wound care"]'::jsonb, 2, 'A previously unvaccinated person with a bite from a stray dog that cannot be observed requires full post-exposure prophylaxis: human rabies immune globulin infiltrated into and around the wound plus a 4-dose rabies vaccine series on days 0, 3, 7, and 14. Vaccine alone is insufficient because immune globulin provides immediate passive protection while the vaccine response develops. Immune globulin alone provides only temporary protection and does not induce lasting immunity, so the vaccine series is essential. Observation is unsafe because the animal cannot be quarantined and rabies is almost always fatal once symptoms appear. A single vaccine dose does not provide adequate protection; the full series is required for previously unvaccinated individuals.', 'Medium', 105, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 30-year-old emergency department nurse sustains a needlestick injury from a hollow-bore needle used on a patient known to be HIV-positive with a viral load of 250,000 copies/mL. The nurse is HIV-negative and the exposure occurred 2 hours ago. Which of the following is the most appropriate next step?', '["Give a single dose of zidovudine and reassess in 1 week", "Wait for the source patient''s confirmatory HIV test before starting any therapy", "Start HIV post-exposure prophylaxis immediately with a 28-day antiretroviral regimen", "Start hepatitis B immune globulin only, since HIV transmission risk is low", "Reassure the nurse and schedule HIV testing in 6 months"]'::jsonb, 2, 'HIV post-exposure prophylaxis should be started as soon as possible, ideally within 2 hours, after a high-risk percutaneous exposure to HIV-positive blood, using a 28-day course of combination antiretroviral therapy. Waiting for confirmatory testing delays treatment and reduces its effectiveness, since PEP is most effective when started early. A single dose of zidovudine is inadequate; current guidelines recommend a three-drug regimen for 28 days. Hepatitis B immune globulin addresses hepatitis B risk, not HIV, and does not substitute for HIV PEP. Reassurance without PEP is inappropriate after a high-risk exposure from a source with a high viral load, because the transmission risk is significant and PEP substantially reduces it.', 'Easy', 106, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 45-year-old man presents with a deep puncture wound to the foot sustained while working in his garden. He reports his last tetanus vaccination was 12 years ago. The wound is contaminated with soil. Which of the following is the most appropriate tetanus prophylaxis?', '["Tetanus immune globulin plus tetanus toxoid", "Tetanus immune globulin alone", "Tetanus toxoid (Td or Tdap) booster alone", "No tetanus prophylaxis is needed", "Tetanus toxoid plus antibiotics only"]'::jsonb, 2, 'This is a tetanus-prone wound in a patient whose last tetanus vaccination was more than 5 years ago, so a tetanus toxoid booster is indicated; immune globulin is not needed because he has a history of prior immunization. Tetanus immune globulin alone is used only when the patient has never been immunized or has an unknown history with a tetanus-prone wound. Combined immune globulin plus toxoid is reserved for patients with no prior immunization or an uncertain history presenting with a tetanus-prone wound. No prophylaxis would be wrong because the wound is dirty, contaminated with soil, and his immunity has waned after 12 years. Antibiotics alone do not prevent tetanus, which is caused by Clostridium tetani toxin, and tetanus prophylaxis requires the toxoid booster.', 'Medium', 107, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 58-year-old man presents with 4 weeks of daily fever to 39.5°C, night sweats, and a 5-kg weight loss. He has no localizing symptoms. Physical examination is unremarkable except for mild splenomegaly. Laboratory tests show anemia, elevated ESR and CRP, and normal liver and kidney function. Blood cultures, chest radiograph, urinalysis, and HIV testing are all negative. CT of the chest, abdomen, and pelvis shows no abscess or mass. Which of the following is the most appropriate next step in the evaluation of this fever of unknown origin?', '["Perform a bone marrow biopsy as the next diagnostic step", "Start empiric broad-spectrum antibiotics immediately", "Obtain a detailed history including travel, animal exposures, medications, and prior infections", "Order a whole-body PET-CT scan immediately", "Begin empiric corticosteroids for presumed adult-onset Still disease"]'::jsonb, 2, 'The most important next step in fever of unknown origin is a meticulous history covering travel, animal and tick exposures, medications, occupational exposures, sexual history, and prior infections, because these details often reveal the diagnosis and guide targeted testing. Empiric broad-spectrum antibiotics are not started in a stable patient with FUO because they can mask the diagnosis, sterilize cultures, and delay identification of the cause. Bone marrow biopsy is invasive and is reserved for later in the workup when there are cytopenias, suspected hematologic malignancy, or other specific indications. Whole-body PET-CT can be useful later in FUO evaluation but is not the first step before a thorough history and repeat examination. Empiric corticosteroids are dangerous without a diagnosis because they can worsen occult infection and obscure the underlying cause.', 'Medium', 108, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 70-year-old woman with a history of polymyalgia rheumatica on low-dose prednisone presents with 6 weeks of intermittent fever, fatigue, and jaw pain when chewing. She has a new murmur on examination. Blood cultures grow Streptococcus viridans. Echocardiography shows a vegetation on the mitral valve. Which of the following is the most likely explanation for her prolonged fever?', '["Giant cell arteritis causing fever and jaw claudication", "Relapse of polymyalgia rheumatica", "Subacute bacterial endocarditis from Streptococcus viridans", "Occult malignancy causing paraneoplastic fever", "Drug fever from chronic prednisone use"]'::jsonb, 2, 'Subacute bacterial endocarditis classically causes prolonged low-grade fever over weeks, and Streptococcus viridans is the most common organism, typically seeding a damaged or prosthetic valve; the vegetation on echocardiography confirms the diagnosis. A polymyalgia rheumatica relapse causes proximal muscle pain and stiffness with elevated inflammatory markers but does not cause a murmur, positive blood cultures, or a valve vegetation. Giant cell arteritis can cause jaw claudication and fever, but it does not explain the murmur, bacteremia, or echocardiographic vegetation. Occult malignancy can cause fever of unknown origin, but it does not explain the positive blood cultures and vegetation. Drug fever from prednisone is uncommon, and corticosteroids more typically suppress fever rather than cause it.', 'Medium', 109, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 62-year-old man is evaluated for 3 weeks of fever, night sweats, and weight loss. He has a history of tuberculosis exposure 20 years ago. His tuberculin skin test is positive at 15 mm, chest radiograph is normal, and sputum acid-fast bacilli smears are negative. CT of the abdomen shows enlarged mesenteric lymph nodes. Which of the following is the most appropriate next step to establish the diagnosis?', '["Order serum QuantiFERON testing to confirm active tuberculosis", "Start empiric four-drug antituberculous therapy without tissue diagnosis", "Repeat sputum smears and cultures only", "Tissue biopsy of the mesenteric lymph nodes for histology and mycobacterial culture", "Begin empiric broad-spectrum antibiotics for bacterial lymphadenitis"]'::jsonb, 3, 'Extrapulmonary tuberculosis presenting as fever of unknown origin with mesenteric lymphadenopathy requires tissue diagnosis, and biopsy of the lymph nodes provides histology showing caseating granulomas and allows mycobacterial culture, which is the gold standard. Empiric antituberculous therapy without tissue confirmation risks treating the wrong disease, since lymphoma and other infections can present identically. Repeat sputum studies are unhelpful because pulmonary disease is absent, as shown by the normal chest radiograph and negative smears. QuantiFERON testing confirms latent infection but cannot distinguish latent from active disease and cannot establish that the lymphadenopathy is tuberculous. Broad-spectrum antibiotics do not treat tuberculosis and would delay diagnosis of a potentially curable infection.', 'Hard', 110, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 68-year-old man in the intensive care unit with a central venous catheter develops new fever and hypotension on day 6 of admission. Blood cultures drawn from the catheter and from a peripheral vein both grow coagulase-negative staphylococci, with the catheter-drawn culture turning positive 3 hours earlier than the peripheral culture. The catheter insertion site shows no erythema or purulence. Which of the following is the most appropriate management?', '["Exchange the catheter over a guidewire and continue observation", "Continue the catheter and start oral antibiotics", "Remove the catheter but withhold antibiotics since the organism is a contaminant", "Remove the central venous catheter and start intravenous vancomycin", "Start broad-spectrum antibiotics and keep the catheter in place"]'::jsonb, 3, 'This is a catheter-related bloodstream infection: the same organism from both cultures with a differential time to positivity of more than 2 hours strongly implicates the catheter as the source, and the recommended management is catheter removal plus systemic antibiotics, with vancomycin covering coagulase-negative staphylococci. Keeping the catheter and using oral antibiotics is inadequate because the infected foreign body sustains bacteremia and oral therapy does not achieve reliable blood levels. Coagulase-negative staphylococci from two separate cultures with differential time to positivity is not a contaminant and requires treatment. Guidewire exchange is not recommended for an infected catheter because the new catheter becomes colonized through the infected tract. Retaining the catheter while giving antibiotics often fails to clear the infection and risks persistent bacteremia and metastatic seeding.', 'Hard', 111, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 74-year-old woman with an indwelling urinary catheter for 10 days develops fever, suprapubic discomfort, and cloudy urine. Urinalysis shows pyuria and bacteriuria. She has no flank pain and her blood pressure is normal. Which of the following is the most appropriate management of her catheter-associated urinary tract infection?', '["Start prophylactic antibiotics and keep the catheter indefinitely", "Continue the same catheter and start broad-spectrum intravenous antibiotics", "Remove the catheter but withhold antibiotics since bacteriuria is expected", "Remove or replace the urinary catheter and start antibiotics based on culture results", "Irrigate the bladder with antiseptic solution and continue the catheter"]'::jsonb, 3, 'Catheter-associated urinary tract infection is managed by removing or replacing the indwelling catheter, which eliminates the colonized foreign body and biofilm, plus antibiotics targeted to urine culture results for symptomatic infection. Continuing the same catheter perpetuates the biofilm and makes eradication unlikely despite antibiotics. Withholding antibiotics is inappropriate because she has symptoms of infection with fever and suprapubic discomfort, not merely asymptomatic bacteriuria. Prophylactic antibiotics do not prevent catheter-associated infection and promote resistance, and keeping the catheter indefinitely increases infection risk. Bladder irrigation with antiseptic does not treat established infection and is not recommended for catheter-associated urinary tract infection.', 'Medium', 112, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 35-year-old man is admitted with measles and is placed in a hospital room. He has a cough and conjunctivitis. The nursing staff asks which isolation precautions are required. Which of the following is the most appropriate infection control measure?', '["Standard precautions only, since measles is not contagious in hospital", "Droplet precautions with a surgical mask within 3 feet", "Contact precautions with gown and gloves only", "Airborne precautions in a negative-pressure room with N95 respirators", "Airborne precautions only until the rash resolves, then standard precautions"]'::jsonb, 3, 'Measles is transmitted by airborne droplet nuclei that remain suspended in air, so airborne precautions are required: a negative-pressure room with at least 6 to 12 air exchanges per hour and N95 respirators for staff, plus immunity verification for healthcare workers. Droplet precautions are used for influenza and pertussis, where large droplets fall within 3 feet, but measles particles are smaller and remain airborne. Contact precautions alone are insufficient because measles spreads through the air, not only by direct contact. Standard precautions alone are inadequate for a highly contagious airborne disease with a secondary attack rate over 90 percent in susceptible contacts. Airborne precautions should continue for the duration of infectivity, which extends from 4 days before to 4 days after rash onset, not merely until the rash appears.', 'Easy', 113, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 60-year-old man undergoes elective colon resection. He receives cefazolin plus metronidazole within 60 minutes before incision, and the operation lasts 5 hours. Postoperatively he is afebrile with a clean wound. Which of the following is the most appropriate antibiotic prophylaxis strategy to prevent surgical site infection?', '["Switch to broad-spectrum vancomycin plus piperacillin-tazobactam for 48 hours", "Continue cefazolin plus metronidazole for 5 days postoperatively", "Continue antibiotics until all drains are removed", "Redose cefazolin intraoperatively and stop antibiotics within 24 hours after surgery", "Stop antibiotics immediately at skin closure without redosing"]'::jsonb, 3, 'For a 5-hour operation, cefazolin should be redosed intraoperatively every 4 hours to maintain adequate tissue levels, and surgical prophylaxis should be discontinued within 24 hours after surgery because longer courses do not reduce surgical site infections and increase resistance and C. difficile risk. Continuing prophylaxis for 5 days provides no additional benefit and increases adverse effects, cost, and antimicrobial resistance. Continuing antibiotics until drain removal is not supported by evidence and prolongs unnecessary exposure. Switching to broader agents postoperatively is inappropriate when the patient is afebrile with a clean wound and no evidence of infection. Stopping without redosing during a prolonged operation risks subtherapeutic tissue levels in the second half of the case, increasing surgical site infection risk.', 'Medium', 114, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 28-year-old woman plans a 3-week trip to rural West Africa in 4 weeks. She will be staying in villages with limited medical care. She has no chronic medical conditions and takes no medications. Which of the following is the most appropriate malaria prophylaxis for her trip?', '["No chemoprophylaxis is needed if she uses insect repellent and bed nets", "Chloroquine weekly, starting 1 week before travel", "Mefloquine weekly, starting 2 weeks before travel", "Doxycycline daily, starting 1 day before travel and continuing 4 weeks after departure", "Atovaquone-proguanil daily, starting 1-2 days before travel and continuing 7 days after departure"]'::jsonb, 4, 'Atovaquone-proguanil is the preferred malaria prophylaxis for short trips to chloroquine-resistant areas of West Africa because it is well tolerated, started only 1 to 2 days before travel, and continued for just 7 days after leaving, which suits her 4-week preparation window. Chloroquine is ineffective in West Africa because Plasmodium falciparum there is chloroquine-resistant. Mefloquine is effective but requires starting 2 to 3 weeks before travel, carries neuropsychiatric side effects, and is less convenient for a trip in 4 weeks. Doxycycline is effective but requires 4 weeks of post-travel dosing and causes photosensitivity and gastrointestinal upset, making it a second choice. Insect repellent and bed nets are important adjuncts but are not sufficient alone in a high-transmission area, where chemoprophylaxis is strongly recommended.', 'Medium', 115, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 42-year-old man returns from a 2-week trip to Mexico with 4 days of watery diarrhea, abdominal cramps, and low-grade fever. He has no blood in the stool and is mildly dehydrated. Stool studies are negative for ova, parasites, and leukocytes. Which of the following is the most appropriate treatment for his traveler''s diarrhea?', '["Intravenous ceftriaxone and hospital admission", "Loperamide alone without antibiotics", "Metronidazole 500 mg orally three times daily for 10 days", "Ciprofloxacin 500 mg orally twice daily for 3 days", "A single dose of azithromycin 1000 mg orally plus oral rehydration"]'::jsonb, 4, 'Moderate traveler''s diarrhea with fever and cramps is best treated with a single dose of azithromycin, which is now preferred over fluoroquinolones because of rising Campylobacter resistance, along with oral rehydration to replace fluid losses. Loperamide alone is insufficient when fever and invasive features are present, and antimotility agents should not be used as sole therapy in febrile dysenteric illness. Metronidazole treats protozoal infections such as giardiasis and amebiasis, but this patient''s negative stool studies and acute watery diarrhea point to bacterial traveler''s diarrhea. Ciprofloxacin was previously first-line but is now less preferred because of fluoroquinolone-resistant Campylobacter, particularly in Mexico and Southeast Asia. Intravenous ceftriaxone and admission are unnecessary for mild dehydration without bloody stool, high fever, or systemic toxicity.', 'Medium', 116, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 55-year-old man is planning a 2-week trip to India in 6 weeks. He will be visiting rural areas and eating local food. He received the hepatitis A vaccine series 10 years ago and the typhoid Vi polysaccharide vaccine 4 years ago. Which of the following is the most appropriate pre-travel recommendation?', '["Defer all vaccines until after the trip to avoid side effects", "Repeat the hepatitis A vaccine series because immunity wanes after 10 years", "No additional vaccines are needed for this trip", "Administer the oral live typhoid vaccine instead of the conjugate vaccine", "Administer the typhoid conjugate vaccine now, since the Vi polysaccharide vaccine is only effective for 2 years"]'::jsonb, 4, 'The Vi polysaccharide typhoid vaccine provides protection for only about 2 years, so a traveler to a typhoid-endemic area whose last dose was 4 years ago needs revaccination, and the typhoid conjugate vaccine is now preferred because it provides longer-lasting immunity. The hepatitis A vaccine series provides long-term, likely lifelong immunity after two doses, so repeating it after 10 years is unnecessary. Saying no vaccines are needed ignores the expired typhoid protection in a traveler visiting rural India. The oral live typhoid vaccine is an alternative but requires multiple doses and is less convenient than the single-dose conjugate vaccine. Deferring vaccines until after the trip defeats the purpose of pre-travel prophylaxis and leaves him unprotected during the period of highest risk.', 'Hard', 117, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 38-year-old man presents in July with 5 days of high fever, severe headache, myalgias, and a diffuse maculopapular rash that involves the palms and soles. He went hiking in North Carolina 10 days ago and recalls removing several ticks. Laboratory tests show thrombocytopenia, hyponatremia, and mildly elevated transaminases. Which of the following is the most appropriate empiric treatment?', '["Supportive care only while awaiting confirmatory serology", "Ceftriaxone 2 g intravenously daily", "Vancomycin plus piperacillin-tazobactam", "Chloramphenicol 50 mg/kg/day intravenously", "Doxycycline 100 mg orally twice daily"]'::jsonb, 4, 'This presentation of fever, headache, myalgias, and a petechial or maculopapular rash involving the palms and soles after tick exposure in the southeastern United States is classic for Rocky Mountain spotted fever, caused by Rickettsia rickettsii, and doxycycline is the treatment of choice and must be started empirically without waiting for serology. Ceftriaxone treats bacterial meningitis and Lyme disease but has no activity against Rickettsia, which are obligate intracellular organisms. Vancomycin plus piperacillin-tazobactam covers bacterial sepsis but not rickettsial infection. Chloramphenicol is a second-line alternative for Rocky Mountain spotted fever but is less effective than doxycycline and carries a risk of aplastic anemia. Waiting for serology is dangerous because antibodies take 7 to 10 days to appear and delayed treatment markedly increases mortality.', 'Medium', 118, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 45-year-old woman presents with 1 week of fever, chills, headache, and myalgias after a camping trip in Wisconsin. She does not recall a tick bite and has no rash. Laboratory tests show leukopenia, thrombocytopenia, and elevated transaminases. Peripheral blood smear shows intracytoplasmic morulae in neutrophils. Which of the following is the most likely diagnosis?', '["Ehrlichiosis caused by Ehrlichia chaffeensis", "Lyme disease caused by Borrelia burgdorferi", "Babesiosis caused by Babesia microti", "Rocky Mountain spotted fever caused by Rickettsia rickettsii", "Human granulocytic anaplasmosis caused by Anaplasma phagocytophilum"]'::jsonb, 4, 'Human granulocytic anaplasmosis presents with fever, leukopenia, thrombocytopenia, and transaminitis after Ixodes tick exposure in the upper Midwest, and the diagnostic finding is intracytoplasmic morulae within neutrophils on peripheral blood smear. Lyme disease typically causes erythema migrans and does not produce morulae in neutrophils or this pattern of cytopenias. Babesiosis causes hemolytic anemia with intraerythrocytic parasites, not morulae in neutrophils, and is more common in the Northeast. Rocky Mountain spotted fever causes a rash involving the palms and soles and does not show morulae in neutrophils. Ehrlichiosis is caused by Ehrlichia chaffeensis, which infects monocytes rather than neutrophils, and is transmitted by Amblyomma ticks in the southeastern United States.', 'Hard', 119, 'MCQ'),
('82e55873-64d5-4a12-bc71-535983609a64', 'A 62-year-old man presents with 2 weeks of fever, fatigue, and confusion after a hiking trip in Minnesota. He has a history of splenectomy. Laboratory tests show hemolytic anemia with hemoglobin 8.5 g/dL, thrombocytopenia, and elevated lactate dehydrogenase. Peripheral blood smear shows intraerythrocytic ring forms with Maltese cross forms. Which of the following is the most appropriate treatment?', '["Trimethoprim-sulfamethoxazole", "Doxycycline alone", "Clindamycin plus quinine", "Ceftriaxone plus doxycycline", "Atovaquone plus azithromycin"]'::jsonb, 4, 'This patient has babesiosis, diagnosed by intraerythrocytic parasites with Maltese cross forms on blood smear, and atovaquone plus azithromycin is the preferred treatment for mild to moderate disease because it is as effective as clindamycin plus quinine with fewer adverse effects. Doxycycline treats anaplasmosis and Lyme disease but has no activity against Babesia, which is a protozoan parasite. Clindamycin plus quinine is an alternative reserved for severe babesiosis because quinine causes significant toxicity including tinnitus and hypoglycemia. Ceftriaxone plus doxycycline treats Lyme disease and anaplasmosis but not babesiosis. Trimethoprim-sulfamethoxazole has no activity against Babesia and is not used for this infection.', 'Hard', 120, 'MCQ');
